    }

    /// The first of an element's data blocks that has what `f` reads.
    pub fn first_data<T>(&self, id: u64, f: impl Fn(&'a [u8]) -> Option<T>) -> Option<T> {
        self.datas(id).into_iter().find_map(f)
    }

    pub fn type_name(&self, id: u64) -> Option<String> {
