pub fn info(path: &str) -> Result<Value, String> {
    let o = open(path)?;
    let elements = match doc::read(&o.container, o.basic.release) {
        Ok(d) => info::elements(&d),
        Err(e) => jobj! {"error" => e},
    };
    Ok(info::build(&o.basic, &o.atom, elements))
}

