//! The model's rules, checked after every command that changes it.

use crate::project::Project;

pub fn check(pr: &Project) -> Result<(), String> {
    core_check(pr)?;
    crate::cloud::check(pr)?;
    crate::media::check(pr)?;
    crate::styles::check(pr)?;
    crate::arch::check(pr)?;
    crate::structure::check(pr)?;
    crate::views::check(pr)?;
    crate::edit::check(pr)?;
    crate::readers::check(pr)?;
    Ok(())
}

fn core_check(pr: &Project) -> Result<(), String> {
    let mut level_names: Vec<String> = Vec::new();
    let mut grid_names: Vec<String> = Vec::new();
    for (id, e) in &pr.elements {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        match cat {
            "level" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if level_names.contains(&name) {
                    return Err(format!("level {}: another level is already named `{}`", id, name));
                }
                level_names.push(name);
                if let Some(ext) = e.get("extent").and_then(|x| x.as_arr()) {
                    let a = ext.first().and_then(crate::commands::params::point_of);
                    let b = ext.get(1).and_then(crate::commands::params::point_of);
                    if let (Some(a), Some(b)) = (a, b) {
                        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
                            return Err(format!(
                                "level {}: its extent runs from its south-west corner to its north-east one",
                                id
                            ));
                        }
                    }
                }
            }
            "grid" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if grid_names.contains(&name) {
                    return Err(format!("grid {}: another grid is already named `{}`", id, name));
                }
                grid_names.push(name);
                let a = e.get("start").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let b = e.get("end").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
                if len <= 1.0 {
                    return Err(format!("grid {}: too short ({} mm)", id, len));
                }
            }
            _ => {}
        }
    }
    Ok(())
}

//! The check-and-drop pass: the model's rules checked on what came in, and the first element
//! that breaks one left out (with the rule's words) until none does.

use super::import::Ctx;
use super::notes::Kind;
use crate::json::Value;
use std::collections::BTreeMap;

fn num(v: &Value, k: &str) -> f64 {
    v.get(k).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

fn level_elev(ctx: &Ctx, g: &str) -> Option<f64> {
    ctx.pr.elements.values().find(|e| e.get("guid").and_then(|x| x.as_str()) == Some(g)).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64())
}

/// The first element (by id) that breaks a rule, and the rule's words.
fn first_failure(ctx: &Ctx) -> Option<(u64, String)> {
    let pr = &ctx.pr;
    let by_guid: BTreeMap<String, u64> = pr
        .elements
        .iter()
        .filter_map(|(id, e)| e.get("guid").and_then(|g| g.as_str()).map(|g| (g.to_string(), *id)))
        .collect();
    for (id, e) in &pr.elements {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        match cat {
            "wall" => {
                let lv = e.get("level").and_then(|l| l.as_str()).and_then(|g| level_elev(ctx, g)).unwrap_or(0.0);
                let base = lv + num(e, "base_offset");
                let top = match e.get("top_level").and_then(|t| t.as_str()).and_then(|g| level_elev(ctx, g)) {
                    Some(t) => t + num(e, "top_offset"),
                    None => base + num(e, "height"),
                };
                if !(top - base > 1.0) {
                    // the heights to the millimetre (half to even), the difference rounded away from zero
                    return Some((
                        *id,
                        format!(
                            "its top ({:.0} mm) must be above its base ({:.0} mm); it comes out {} mm tall, so raise its top constraint, top offset or height by more than {} mm",
                            top,
                            base,
                            (top - base).round() as i64,
                            (base - top).round() as i64
                        ),
                    ));
                }
            }
            "door" | "window" => {
                let host = e.get("host").and_then(|h| h.as_str()).unwrap_or("");
                let hid = match by_guid.get(host) {
                    Some(h) => *h,
                    None => return Some((*id, "its wall was left out".into())),
                };
                let _ = hid;
                // two openings may not share a place along their wall
                let w = super::build::type_value(pr, cat, &type_name(ctx, e).unwrap_or_default()).map(|t| num(t, "width")).unwrap_or(0.0);
                let (a0, a1) = (num(e, "offset") - w / 2.0, num(e, "offset") + w / 2.0);
                for (id2, e2) in pr.elements.range(id + 1..) {
                    let c2 = e2.get("category").and_then(|c| c.as_str()).unwrap_or("");
                    if !(c2 == "door" || c2 == "window") || e2.get("host").and_then(|h| h.as_str()) != Some(host) {
                        continue;
                    }
                    let w2 = super::build::type_value(pr, c2, &type_name(ctx, e2).unwrap_or_default()).map(|t| num(t, "width")).unwrap_or(0.0);
                    let (b0, b1) = (num(e2, "offset") - w2 / 2.0, num(e2, "offset") + w2 / 2.0);
                    if a0.max(b0) < a1.min(b1) - 1e-6 {
                        return Some((*id, format!("{} {} and {} {} overlap in wall {}", cat, id, c2, id2, host)));
                    }
                }
            }
            "roof" => {
                if let Some(r) = roof_rule(e) {
                    return Some((*id, r));
                }
            }
            "pipe" | "duct" | "cabletray" => {
                let a = e.get("start").and_then(point).unwrap_or([0.0, 0.0]);
                let b = e.get("end").and_then(point).unwrap_or([0.0, 0.0]);
                let z0 = num(e, "offset");
                let z1 = e.get("end_offset").and_then(|x| x.as_f64()).unwrap_or(z0);
                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2) + (z1 - z0).powi(2)).sqrt();
                if !(len > 1.0) {
                    return Some((*id, format!("too short ({} mm)", len)));
                }
            }
            _ => {}
        }
    }
    None
}

fn point(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    Some([a.first()?.as_f64()?, a.get(1)?.as_f64()?])
}

/// The rules a roof the import makes can break: an extrusion's line, profile and sweep, and a
/// footprint's boundary.
fn roof_rule(e: &Value) -> Option<String> {
    if let Some(x) = e.get("extrusion") {
        let line: Vec<[f64; 2]> = x.get("line").and_then(|l| l.as_arr()).map(|a| a.iter().filter_map(point).collect()).unwrap_or_default();
        if line.len() == 2 {
            let len = ((line[1][0] - line[0][0]).powi(2) + (line[1][1] - line[0][1]).powi(2)).sqrt();
            if !(len > 1.0) {
                return Some(format!("too short ({} mm)", len));
            }
        }
        let prof: Vec<[f64; 2]> = x.get("profile").and_then(|l| l.as_arr()).map(|a| a.iter().filter_map(point).collect()).unwrap_or_default();
        if prof.len() < 2 || prof.len() > 10000 {
            return Some("an extrusion's profile needs 2 to 10000 points".into());
        }
        if prof.windows(2).any(|w| !(w[1][0] - w[0][0] > 1.0)) {
            return Some("its profile runs along its line one way, each point past the one before".into());
        }
        if !(num(x, "to") - num(x, "from") > 1.0) {
            return Some("it's swept across its line from `from` to `to`, further to the left".into());
        }
        return None;
    }
    let b: Vec<[f64; 2]> = e.get("boundary").and_then(|l| l.as_arr()).map(|a| a.iter().filter_map(point).collect()).unwrap_or_default();
    if b.len() < 3 || b.len() > 10000 {
        return Some("a boundary needs 3 to 10000 points".into());
    }
    if !(super::plan::area(&b).abs() > 1.0) {
        return Some("its boundary encloses no area".into());
    }
    None
}

fn type_name(ctx: &Ctx, e: &Value) -> Option<String> {
    let g = e.get("type")?.as_str()?;
    if let Some(n) = ctx.pr.lib_name(g) {
        return Some(n);
    }
    ctx.lib_guids.iter().find(|(_, v)| v.as_str() == g).map(|((_, n), _)| n.clone())
}

pub fn run(ctx: &mut Ctx) {
    loop {
        let (id, reason) = match first_failure(ctx) {
            Some(x) => x,
            None => break,
        };
        let e = ctx.pr.elements.remove(&id).unwrap();
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        let rid = ctx.made.iter().find(|(_, (pid, _))| *pid == id).map(|((r, _), _)| *r);
        if let Some(rid) = rid {
            ctx.notes.leave(&Kind::simple(&cat), &reason, rid);
        }
    }
}
//! Building the BIMCraft project an import makes: a new project's library and sections, the
//! types the file's elements need (named apart when they differ), and the library registered.

use crate::json::{Map, Value};
use crate::project::Project;

/// A new project as an import starts it: the default library, no elements.
pub fn new_project(name: &str) -> Project {
    let mut pr = Project::new("en");
    pr.elements.clear();
    pr.doc.insert("name", Value::s(name));
    pr.doc.insert("next_id", Value::u(100000));
    pr
}

/// Rounds a length to a thousandth of a millimetre, as the import writes them.
pub fn r3(x: f64) -> f64 {
    let v = (x * 1000.0).round() / 1000.0;
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

/// Rounds to a millionth (an angle in degrees).
pub fn r6(x: f64) -> f64 {
    let v = (x * 1e6).round() / 1e6;
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

/// Feet to millimetres, rounded.
pub fn mm(ft: f64) -> f64 {
    r3(ft * 304.8)
}

/// A value with its `id` and `guid` keys taken out, at any depth (to compare types).
fn strip_ids(v: &Value) -> Value {
    match v {
        Value::Obj(m) => {
            let mut o = Map::new();
            for (k, x) in &m.items {
                if k == "id" || k == "guid" {
                    continue;
                }
                o.items.push((k.clone(), strip_ids(x)));
            }
            Value::Obj(o)
        }
        Value::Arr(a) => Value::Arr(a.iter().map(strip_ids).collect()),
        _ => v.clone(),
    }
}

/// The types section of a category (`wall`, …, or a run kind under `runs`).
fn types_map<'a>(pr: &'a mut Project, cat: &str) -> &'a mut Map {
    let types = pr.section_mut("types");
    let (outer, inner) = match cat {
        "pipe" | "duct" | "cabletray" | "conduit" | "cable" | "beam" | "wire" => ("runs", Some(cat)),
        _ => (cat, None),
    };
    if !types.contains(outer) {
        types.insert(outer, Value::obj());
    }
    let mut m = types.get_mut(outer).unwrap().as_obj_mut().unwrap();
    if let Some(i) = inner {
        if !m.contains(i) {
            m.insert_sorted(i, Value::obj());
        }
        m = m.get_mut(i).unwrap().as_obj_mut().unwrap();
    }
    m
}

/// Adds a type under a name, or finds the one that is the same; another with the same name and
/// other values is named `Name (2)`, `Name (3)`…. Returns the name it has.
pub fn add_type(pr: &mut Project, cat: &str, name: &str, v: Value) -> String {
    let m = types_map(pr, cat);
    let want = strip_ids(&v);
    let mut k = 1;
    loop {
        let cand = if k == 1 { name.to_string() } else { format!("{} ({})", name, k) };
        match m.get(&cand) {
            Some(x) => {
                if strip_ids(x) == want {
                    return cand;
                }
            }
            None => {
                m.insert_sorted(&cand, v);
                return cand;
            }
        }
        k += 1;
    }
}

/// Adds a type under a name unless one has it already (a run's type is known by its name).
pub fn add_type_once(pr: &mut Project, cat: &str, name: &str, v: Value) -> String {
    let m = types_map(pr, cat);
    if !m.contains(name) {
        m.insert_sorted(name, v);
    }
    name.to_string()
}

pub fn type_value<'a>(pr: &'a Project, cat: &str, name: &str) -> Option<&'a Value> {
    let types = pr.section("types")?;
    match cat {
        "pipe" | "duct" | "cabletray" | "conduit" | "cable" | "beam" | "wire" => types.get("runs")?.get(cat)?.get(name),
        _ => types.get(cat)?.get(name),
    }
}

/// The library kind of a type of a category.
pub fn type_kind(cat: &str) -> String {
    match cat {
        "structural_column" => "type:structuralcolumn".to_string(),
        _ => format!("type:{}", cat),
    }
}

/// The GUID a material has in the library, by its name.
pub fn material_guid(pr: &Project, name: &str) -> Option<String> {
    pr.lib_guid("material", name)
}

/// Registers in the library what the sections hold and it has not (types, families, their types
/// and parameters), then gives the new layers and forms their ids.
pub fn sync_library(pr: &mut Project, made: &std::collections::BTreeMap<(String, String), String>) {
    let mut add: Vec<(String, String)> = Vec::new();
    if let Some(types) = pr.section("types") {
        for (cat, ts) in types.iter() {
            if cat == "runs" {
                if let Some(runs) = ts.as_obj() {
                    for (run, rts) in runs.iter() {
                        if let Some(rts) = rts.as_obj() {
                            for (name, _) in rts.iter() {
                                add.push((format!("type:{}", run), name.clone()));
                            }
                        }
                    }
                }
                continue;
            }
            if let Some(ts) = ts.as_obj() {
                for (name, _) in ts.iter() {
                    add.push((type_kind(cat), name.clone()));
                }
            }
        }
    }
    let mut fam_names: Vec<String> = Vec::new();
    let mut fam_types: Vec<String> = Vec::new();
    let mut fam_params: Vec<String> = Vec::new();
    if let Some(f) = pr.section("families") {
        for (name, fv) in f.iter() {
            fam_names.push(name.clone());
            if let Some(ts) = fv.get("types").and_then(|t| t.as_obj()) {
                for (t, _) in ts.iter() {
                    fam_types.push(format!("{}: {}", name, t));
                }
            }
            if let Some(ps) = fv.get("parameters").and_then(|p| p.as_arr()) {
                for p in ps {
                    if let Some(n) = p.get("name").and_then(|n| n.as_str()) {
                        fam_params.push(format!("{}: {}", name, n));
                    }
                }
            }
        }
    }
    for n in fam_names {
        add.push(("family".into(), n));
    }
    for n in fam_types {
        add.push(("family-type".into(), n));
    }
    for n in fam_params {
        add.push(("family-parameter".into(), n));
    }
    for (kind, name) in add {
        if pr.lib_find(&kind, &name).is_none() {
            let id = pr.alloc_lib_id();
            let g = made.get(&(kind.clone(), name.clone())).cloned().unwrap_or_else(crate::rand::guid);
            pr.library.insert(id, crate::jobj! {"kind" => kind.as_str(), "name" => name.as_str(), "guid" => g});
        }
    }
    // ids for the parts that have none: layers of types, forms of families
    let mut paths: Vec<(String, Vec<String>, usize)> = Vec::new();
    if let Some(types) = pr.section("types") {
        for (cat, ts) in types.iter() {
            if cat == "runs" {
                continue;
            }
            if let Some(ts) = ts.as_obj() {
                for (name, t) in ts.iter() {
                    if let Some(ls) = t.get("layers").and_then(|l| l.as_arr()) {
                        for (i, l) in ls.iter().enumerate() {
                            if l.get("id").is_none() {
                                paths.push(("types".into(), vec![cat.clone(), name.clone(), "layers".into()], i));
                            }
                        }
                    }
                }
            }
        }
    }
    if let Some(f) = pr.section("families") {
        for (name, fv) in f.iter() {
            if let Some(fs) = fv.get("forms").and_then(|l| l.as_arr()) {
                for (i, l) in fs.iter().enumerate() {
                    if l.get("id").is_none() {
                        paths.push(("families".into(), vec![name.clone(), "forms".into()], i));
                    }
                }
            }
        }
    }
    for (sec, path, i) in paths {
        let id = pr.alloc_lib_id();
        let mut v: &mut Value = pr.doc.get_mut(&sec).unwrap();
        for k in &path {
            v = v.get_mut(k).unwrap();
        }
        let item = &mut v.as_arr_mut().unwrap()[i];
        // the id goes first, as the core writes a part
        if let Value::Obj(m) = item {
            let mut n = Map::new();
            n.items.push(("id".into(), Value::u(id)));
            for (k, x) in m.items.drain(..) {
                n.items.push((k, x));
            }
            *m = n;
        }
    }
}

