#!/usr/bin/env python3
"""Show what of a project differs from the default project: top-level sections changed, and the elements."""
import json
import re
import sys


def load(p):
    s = open(p).read()
    s = re.sub(r'"uid": \d+', '"uid": 0', s)
    return json.loads(s)


GUID = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')


def strip(v):
    if isinstance(v, dict):
        return {k: strip(x) for k, x in v.items() if k not in ('guid', 'id')}
    if isinstance(v, list):
        return [strip(x) for x in v]
    if isinstance(v, str) and GUID.match(v):
        return 'G'
    return v


