#!/usr/bin/env python3
"""Show what of a project differs from the default project: top-level sections changed, and the elements."""
import json
import re
import sys


def load(p):
    s = open(p).read()
    s = re.sub(r'"uid": \d+', '"uid": 0', s)
    return json.loads(s)


GUID = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')


def strip(v):
    if isinstance(v, dict):
        return {k: strip(x) for k, x in v.items() if k not in ('guid', 'id')}
    if isinstance(v, list):
        return [strip(x) for x in v]
    if isinstance(v, str) and GUID.match(v):
        return 'G'
    return v


d0 = load('/tmp/ifc-import-agent/default.bimcraft')
d = load(sys.argv[1])
show_el = '-e' in sys.argv
for k in d:
    if k in ('elements',):
        continue
    if k == 'library':
        l0 = {(v['kind'], v['name']) for v in d0['library'].values()}
        new = [(i, v['kind'], v['name']) for i, v in d['library'].items() if (v['kind'], v['name']) not in l0]
        print('library new:', len(new))
        for x in new[:80]:
            print('   ', x)
        continue
    if k not in d0:
        print('NEW SECTION', k, json.dumps(d[k])[:3000])
        continue
    if strip(d[k]) != strip(d0[k]):
        a, b = strip(d[k]), strip(d0[k])
        if isinstance(a, dict) and isinstance(b, dict):
            for kk in a:
                if kk not in b:
                    print('section', k, 'new key', kk, json.dumps(d[k][kk])[:3000])
                elif a[kk] != b[kk]:
                    print('section', k, 'changed key', kk, json.dumps(d[k][kk])[:3000])
            for kk in b:
                if kk not in a:
                    print('section', k, 'lost key', kk)
        else:
            print('section', k, 'changed:', json.dumps(d[k])[:2000])
cats = {}
for i, e in d['elements'].items():
    cats.setdefault(e.get('category'), []).append(i)
print({c: len(v) for c, v in cats.items()})
if show_el:
    for i, e in d['elements'].items():
        print(i, json.dumps(e))

