#!/usr/bin/env python3
"""Key shapes of elements by category across the expected conversions."""
import glob
import json
import re
from collections import defaultdict

shapes = defaultdict(lambda: defaultdict(list))
for f in sorted(glob.glob('/tmp/ifc-import-agent/expected/*.bimcraft')):
    d = json.loads(re.sub(r'"uid": \d+', '"uid": 0', open(f).read()))
    for i, e in d['elements'].items():
        shapes[e['category']][tuple(e.keys())].append((f.split('/')[-1], i))
for c, s in shapes.items():
    print(c)
    for k, v in s.items():
        print('   ', list(k), len(v), v[0])

