import glob
import json
import re
from collections import Counter

c = Counter()
for f in sorted(glob.glob('/tmp/ifc-import-agent/expected/*.bimcraft')):
    d = json.loads(re.sub(r'"uid": \d+', '"uid": 0', open(f).read()))

    def scan(v, path):
        if isinstance(v, dict):
            if 'id' in v and isinstance(v['id'], int):
                c[re.sub(r'\[\d+\]', '[]', re.sub(r'^(types/[^/]+|families)/[^/]+', r'\1/*', path))] += 1
            for k, x in v.items():
                scan(x, path + '/' + k)
        elif isinstance(v, list):
            for i, x in enumerate(v):
                scan(x, path + '[%d]' % i)
    for k, v in d.items():
        if k in ('elements', 'library'):
            continue
        scan(v, k)
for k, v in c.items():
    print(v, k)

