//! Building the project an IFC import makes: a new project's library and sections, the types
//! the file's elements need (named apart when they differ), and the library numbered again in
//! the order a project lists it.

use crate::json::{Map, Value};
use crate::project::Project;
use std::collections::BTreeMap;

/// A new project as an import starts it: the default library, no elements.
pub fn new_project(name: &str) -> Project {
    let mut pr = Project::new("en");
    pr.elements.clear();
    pr.doc.insert("name", Value::s(name));
    pr.doc.insert("next_id", Value::u(100000));
    pr
}

/// Rounds a length to a thousandth of a millimetre, as the import writes them (a negative zero
/// stays one).
pub fn r3(x: f64) -> f64 {
    (x * 1000.0).round() / 1000.0
}

/// r3 with a negative zero made zero.
pub fn r3z(x: f64) -> f64 {
    let v = r3(x);
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

/// Rounds to a millionth (an angle in degrees).
pub fn r6(x: f64) -> f64 {
    let v = (x * 1e6).round() / 1e6;
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

/// A number as a name shows it: `200`, `152.5`.
pub fn num_name(x: f64) -> String {
    let v = r3(x);
    if v == v.trunc() && v.abs() < 1e15 {
        format!("{}", v as i64)
    } else {
        format!("{}", v)
    }
}

/// A value with its `id` and `guid` keys taken out, at any depth (to compare types).
pub fn strip_ids(v: &Value) -> Value {
    match v {
        Value::Obj(m) => {
            let mut o = Map::new();
            for (k, x) in &m.items {
                if k == "id" || k == "guid" {
                    continue;
                }
                o.items.push((k.clone(), strip_ids(x)));
            }
            Value::Obj(o)
        }
        Value::Arr(a) => Value::Arr(a.iter().map(strip_ids).collect()),
        _ => v.clone(),
    }
}

pub fn is_run(cat: &str) -> bool {
    matches!(
        cat,
        "beam" | "cable" | "cabletray" | "conduit" | "downconductor" | "duct" | "groundconductor" | "pipe" | "stripfooting" | "wire"
    )
}

/// The types section of a category (`wall`, …, or a run kind under `runs`).
pub fn types_map<'a>(pr: &'a mut Project, cat: &str) -> &'a mut Map {
    let types = pr.section_mut("types");
    let (outer, inner) = if is_run(cat) { ("runs", Some(cat)) } else { (cat, None) };
    if !types.contains(outer) {
        types.insert(outer, Value::obj());
    }
    let mut m = types.get_mut(outer).unwrap().as_obj_mut().unwrap();
    if let Some(i) = inner {
        if !m.contains(i) {
            m.insert_sorted(i, Value::obj());
        }
        m = m.get_mut(i).unwrap().as_obj_mut().unwrap();
    }
    m
}

pub fn type_value<'a>(pr: &'a Project, cat: &str, name: &str) -> Option<&'a Value> {
    let types = pr.section("types")?;
    if is_run(cat) {
        types.get("runs")?.get(cat)?.get(name)
    } else {
        types.get(cat)?.get(name)
    }
}

/// Adds a type under a name, or finds the one that is the same; another with the same name and
/// other values is named `Name (2)`, `Name (3)`…. Returns the name it has.
pub fn add_type(pr: &mut Project, cat: &str, name: &str, v: Value) -> String {
    let m = types_map(pr, cat);
    let want = strip_ids(&v);
    let mut k = 1;
    loop {
        let cand = if k == 1 { name.to_string() } else { format!("{} ({})", name, k) };
        match m.get(&cand) {
            Some(x) => {
                if strip_ids(x) == want {
                    return cand;
                }
            }
            None => {
                m.insert_sorted(&cand, v);
                return cand;
            }
        }
        k += 1;
    }
}

/// The library kind of a type of a category.
pub fn type_kind(cat: &str) -> String {
    match cat {
        "structural_column" => "type:structuralcolumn".to_string(),
        _ => format!("type:{}", cat),
    }
}

/// The GUIDs library entries are to have, by (kind, name), before the library is numbered.
#[derive(Default)]
pub struct LibGuids {
    pub map: BTreeMap<(String, String), String>,
}

impl LibGuids {
    /// The GUID of an entry: the one the library has, the one given before, or a new one.
    pub fn get(&mut self, pr: &Project, kind: &str, name: &str) -> String {
        if let Some(g) = pr.lib_guid(kind, name) {
            return g;
        }
        self.map.entry((kind.to_string(), name.to_string())).or_insert_with(crate::rand::guid).clone()
    }
}

const DEFAULT_PHASES: &[&str] = &["Existing", "New Construction"];
const DEFAULT_PHASE_FILTERS: &[&str] = &["Show All", "Show Complete", "Show New", "Show Previous + Demolished", "Show Previous + New"];

/// The library's entries in the order a project lists them.
fn library_order(pr: &Project) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    let keys = |k: &str| -> Vec<String> { pr.section(k).map(|m| m.keys().cloned().collect()).unwrap_or_default() };
    if let Some(types) = pr.section("types") {
        for (cat, ts) in types.iter() {
            if cat == "runs" {
                if let Some(runs) = ts.as_obj() {
                    for (run, rts) in runs.iter() {
                        if let Some(rts) = rts.as_obj() {
                            for (name, _) in rts.iter() {
                                out.push((format!("type:{}", run), name.clone()));
                            }
                        }
                    }
                }
                continue;
            }
            if let Some(ts) = ts.as_obj() {
                for (name, _) in ts.iter() {
                    out.push((type_kind(cat), name.clone()));
                }
            }
        }
    }
    for n in keys("materials") {
        out.push(("material".into(), n));
    }
    for n in keys("images") {
        out.push(("image".into(), n));
    }
    for n in keys("families") {
        out.push(("family".into(), n));
    }
    for n in keys("parameters") {
        out.push(("parameter".into(), n));
    }
    for n in keys("view_filters") {
        out.push(("view-filter".into(), n));
    }
    for n in keys("view_templates") {
        out.push(("view-template".into(), n));
    }
    match pr.doc.get("phases").and_then(|p| p.as_arr()) {
        Some(a) => {
            for p in a {
                if let Some(s) = p.as_str() {
                    out.push(("phase".into(), s.to_string()));
                }
            }
        }
        None => {
            for p in DEFAULT_PHASES {
                out.push(("phase".into(), p.to_string()));
            }
        }
    }
    match pr.section("phase_filters") {
        Some(m) => {
            for n in m.keys() {
                out.push(("phase-filter".into(), n.clone()));
            }
        }
        None => {
            for p in DEFAULT_PHASE_FILTERS {
                out.push(("phase-filter".into(), p.to_string()));
            }
        }
    }
    if let Some(os) = pr.section("option_sets") {
        for n in os.keys() {
            out.push(("option-set".into(), n.clone()));
        }
        for (n, s) in os.iter() {
            if let Some(opts) = s.get("options").and_then(|o| o.as_arr()) {
                for o in opts {
                    if let Some(o) = o.as_str() {
                        out.push(("design-option".into(), format!("{}: {}", n, o)));
                    }
                }
            }
        }
    }
    if let Some(f) = pr.section("families") {
        for (name, fv) in f.iter() {
            if let Some(ts) = fv.get("types").and_then(|t| t.as_obj()) {
                for (t, _) in ts.iter() {
                    out.push(("family-type".into(), format!("{}: {}", name, t)));
                }
            }
        }
        for (name, fv) in f.iter() {
            if let Some(ps) = fv.get("parameters").and_then(|p| p.as_arr()) {
                for p in ps {
                    if let Some(n) = p.get("name").and_then(|n| n.as_str()) {
                        out.push(("family-parameter".into(), format!("{}: {}", name, n)));
                    }
                }
            }
        }
    }
    for (sec, kind) in [
        ("line_patterns", "line-pattern"),
        ("line_styles", "line-style"),
        ("fill_patterns", "fill-pattern"),
        ("region_types", "filled-region-type"),
        ("text_types", "text-type"),
        ("dimension_types", "dimension-type"),
        ("detail_groups", "detail-group"),
        ("voltages", "voltage"),
        ("distribution_systems", "distribution-system"),
        ("wire_types", "wire-type"),
    ] {
        for n in keys(sec) {
            out.push((kind.into(), n));
        }
    }
    out
}

/// Numbers the library again from 999999 down, in the order a project lists it, each entry
/// keeping its GUID (the library's, else the one given, else a new one); then the parts that
/// carry ids (types' layers, families' forms, symbols and connectors) after them.
pub fn renumber(pr: &mut Project, given: &LibGuids) {
    let order = library_order(pr);
    let mut lib: BTreeMap<u64, Value> = BTreeMap::new();
    let mut id = 999_999u64;
    for (kind, name) in order {
        let g = pr
            .lib_guid(&kind, &name)
            .or_else(|| given.map.get(&(kind.clone(), name.clone())).cloned())
            .unwrap_or_else(crate::rand::guid);
        lib.insert(id, crate::jobj! {"kind" => kind.as_str(), "name" => name.as_str(), "guid" => g});
        id -= 1;
    }
    pr.library = lib;
    // the parts
    let mut set_id = |item: &mut Value, id: &mut u64| {
        if let Value::Obj(m) = item {
            let mut n = Map::new();
            n.items.push(("id".into(), Value::u(*id)));
            if !m.contains("guid") {
                n.items.push(("guid".into(), Value::s(&crate::rand::guid())));
            }
            for (k, x) in m.items.drain(..) {
                if k == "id" {
                    continue;
                }
                n.items.push((k, x));
            }
            *m = n;
            *id -= 1;
        }
    };
    if let Some(Value::Obj(types)) = pr.doc.get_mut("types") {
        for (cat, ts) in types.items.iter_mut() {
            if cat == "runs" {
                continue;
            }
            if let Value::Obj(ts) = ts {
                for (_, t) in ts.items.iter_mut() {
                    if let Some(Value::Arr(ls)) = t.get_mut("layers") {
                        for l in ls.iter_mut() {
                            set_id(l, &mut id);
                        }
                    }
                }
            }
        }
    }
    if let Some(Value::Obj(fams)) = pr.doc.get_mut("families") {
        for (_, f) in fams.items.iter_mut() {
            for part in ["forms", "symbols", "connectors"] {
                if let Some(Value::Arr(ls)) = f.get_mut(part) {
                    for l in ls.iter_mut() {
                        set_id(l, &mut id);
                    }
                }
            }
        }
    }
    pr.lib_low = id + 1;
}

//! Reading IFC2x3 and IFC4 files into a project.

use super::import_build::{self as build, LibGuids};
use super::import_geom as geom;
use super::import_model::{guid_of_global_id, Model};
use super::step;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use std::collections::{BTreeMap, BTreeSet};

/// A level of the project as the import knows it.
#[derive(Clone, Debug)]
pub struct Lvl {
    /// The storey's entity, if it came from one.
    pub ent: Option<u64>,
    pub name: String,
    pub elevation: f64,
    pub guid: String,
}

/// An element that came in.
#[derive(Clone, Debug)]
pub struct Made {
    pub id: u64,
    pub guid: String,
    pub cat: String,
}

pub struct Ctx {
    pub m: Model,
    pub pr: Project,
    pub path: String,
    pub levels: Vec<Lvl>,
    pub skipped: Vec<String>,
    /// The file's entities that came in, and what they became.
    pub made: BTreeMap<u64, Made>,
    pub used_guids: BTreeSet<String>,
    pub lib: LibGuids,
    /// What later passes need of the walls: entity → its measured line.
    pub walls: BTreeMap<u64, super::import_walls::WallLine>,
}

impl Ctx {
    /// The GUID an entity comes in with: its GlobalId's, unless it is no GUID or one already
    /// taken; then a new one.
    pub fn guid_for(&mut self, ent: u64) -> String {
        let g = self.m.get(ent).and_then(|e| e.p(0).str()).and_then(guid_of_global_id);
        let g = match g {
            Some(g) if !self.used_guids.contains(&g) => g,
            _ => crate::rand::guid(),
        };
        self.used_guids.insert(g.clone());
        g
    }

    /// Adds an element; returns its project id.
    pub fn add(&mut self, ent: u64, v: Value) -> u64 {
        let id = self.pr.alloc_id();
        let g = v.get("guid").and_then(|g| g.as_str()).unwrap_or("").to_string();
        let cat = v.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        self.pr.elements.insert(id, v);
        self.made.insert(ent, Made { id, guid: g, cat });
        id
    }

    /// Says an element was left out, and why.
    pub fn skip(&mut self, ent: u64, why: &str) {
        let line = self.describe(ent);
        self.skipped.push(format!("{}: {}", line, why));
    }

    /// `IFCWALL #39 'W'`: an element as the reply names it.
    pub fn describe(&self, ent: u64) -> String {
        let class = self.m.class(ent).to_string();
        match self.m.name(ent) {
            Some(n) => format!("{} #{} '{}'", class, ent, n),
            None => format!("{} #{}", class, ent),
        }
    }

    pub fn type_guid(&mut self, cat: &str, name: &str) -> String {
        let kind = build::type_kind(cat);
        self.lib.get(&self.pr, &kind, name)
    }

    pub fn level_guid(&self, i: usize) -> Value {
        Value::s(&self.levels[i].guid)
    }

    /// The level an element stands on: its storey's, else the highest at or below `z`, else the
    /// lowest.
    pub fn level_of(&self, ent: u64, z: f64) -> usize {
        if let Some(s) = self.m.container(ent) {
            if let Some(i) = self.levels.iter().position(|l| l.ent == Some(s)) {
                return i;
            }
        }
        self.level_at(z)
    }

    /// The highest level at or below `z` (within a millimetre), else the lowest.
    pub fn level_at(&self, z: f64) -> usize {
        let mut best: Option<usize> = None;
        for (i, l) in self.levels.iter().enumerate() {
            if l.elevation <= z + 1.0 {
                best = Some(i);
            }
        }
        best.unwrap_or(0)
    }

    /// A level whose elevation is at `z` (within a millimetre), above level `base`.
    pub fn level_at_top(&self, base: usize, z: f64) -> Option<usize> {
        for (i, l) in self.levels.iter().enumerate() {
            if i != base && (l.elevation - z).abs() <= 1.0 && l.elevation > self.levels[base].elevation {
                return Some(i);
            }
        }
        None
    }
}

fn file_stem(path: &str) -> String {
    std::path::Path::new(path).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()
}

/// Imports an IFC file as a new project into the session (what `run x.ifc`, `convert` and
/// `open` do); returns the reply `run` prints. An error is what follows `open: `.
pub fn import(s: &mut Session, path: &str) -> Result<Value, String> {
    let bytes = std::fs::read(path).map_err(|e| format!("{}: {}", path, crate::commands::io_err(&e)))?;
    let (pr, reply) = read(&bytes, path)?;
    s.project = pr;
    s.now_phase = None;
    s.now_option = None;
    s.path = None;
    s.undo.clear();
    s.redo.clear();
    Ok(reply)
}

/// Reads an IFC file's bytes into a project, and the reply an import makes.
pub fn read(bytes: &[u8], path: &str) -> Result<(Project, Value), String> {
    let f = step::parse(bytes).map_err(|e| format!("{}: {}", path, e))?;
    let schema = f.schema();
    if schema.is_empty() {
        return Err(format!("{}: this STEP file is in no schema, not IFC", path));
    }
    if !schema.starts_with("IFC") {
        return Err(format!("{}: this STEP file is in {}, not IFC", path, schema));
    }
    let project = f.entities.iter().find(|(_, e)| e.name == "IFCPROJECT").map(|(id, _)| *id);
    let project = match project {
        Some(p) => p,
        None => return Err(format!("{}: it has no IfcProject", path)),
    };
    let mut m = Model::new(f, schema.clone());
    m.read_units(project);
    let name = match m.name(project).map(|n| n.trim().to_string()) {
        Some(n) if !n.is_empty() => n,
        _ => file_stem(path),
    };
    let pr = build::new_project(&name);
    let mut ctx = Ctx {
        m,
        pr,
        path: path.to_string(),
        levels: Vec::new(),
        skipped: Vec::new(),
        made: BTreeMap::new(),
        used_guids: BTreeSet::new(),
        lib: LibGuids::default(),
        walls: BTreeMap::new(),
    };
    levels(&mut ctx);
    elements(&mut ctx);
    let moved = move_near_origin(&mut ctx);
    build::renumber(&mut ctx.pr, &ctx.lib);
    let reply = reply(&ctx, &schema, &name, path, moved);
    Ok((ctx.pr, reply))
}

/// The storeys as levels, from the lowest up (ties in the file's order), named apart.
fn levels(ctx: &mut Ctx) {
    let mut found: Vec<(f64, u64, String)> = Vec::new();
    for id in ctx.m.of("IFCBUILDINGSTOREY").to_vec() {
        let e = ctx.m.get(id).unwrap();
        let elev = match e.p(5).r() {
            Some(lp) if ctx.m.get(lp).map(|x| x.name == "IFCLOCALPLACEMENT").unwrap_or(false) => geom::placement(&ctx.m, lp).t[2],
            _ => e.p(9).num().map(|x| x * ctx.m.scale).filter(|x| x.is_finite()).unwrap_or(0.0),
        };
        let name = e.p(2).str().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).unwrap_or_else(|| "Level".to_string());
        found.push((build::r3(elev), id, name));
    }
    found.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal).then(a.1.cmp(&b.1)));
    let mut used: Vec<String> = Vec::new();
    for (elev, id, name) in found {
        let mut n = name.clone();
        let mut k = 2;
        while used.contains(&n) {
            n = format!("{} ({})", name, k);
            k += 1;
        }
        used.push(n.clone());
        let g = ctx.guid_for(id);
        let v = crate::jobj! {
            "guid" => g.as_str(),
            "category" => "level",
            "name" => n.as_str(),
            "elevation" => elev,
            "view_range" => crate::jobj!{"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0},
        };
        ctx.add(id, v);
        ctx.levels.push(Lvl { ent: Some(id), name: n, elevation: elev, guid: g });
    }
    if ctx.levels.is_empty() {
        let g = crate::rand::guid();
        let v = crate::jobj! {
            "guid" => g.as_str(),
            "category" => "level",
            "name" => "Level 1",
            "elevation" => 0.0,
            "view_range" => crate::jobj!{"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0},
        };
        let id = ctx.pr.alloc_id();
        ctx.pr.elements.insert(id, v);
        ctx.levels.push(Lvl { ent: None, name: "Level 1".into(), elevation: 0.0, guid: g });
    }
}

/// The elements, kind by kind.
fn elements(ctx: &mut Ctx) {
    super::import_walls::walls(ctx);
    super::import_walls::openings(ctx);
}

/// A model at map coordinates moved near the origin: by the lowest corner of what came in, when
/// that is further than 100 km away.
fn move_near_origin(ctx: &mut Ctx) -> Value {
    let mut lo = [f64::INFINITY, f64::INFINITY];
    for e in ctx.pr.elements.values() {
        for k in ["start", "end", "at", "point"] {
            if let Some(p) = e.get(k).and_then(|p| p.as_arr()) {
                if let (Some(x), Some(y)) = (p.first().and_then(|v| v.as_f64()), p.get(1).and_then(|v| v.as_f64())) {
                    lo[0] = lo[0].min(x);
                    lo[1] = lo[1].min(y);
                }
            }
        }
        for k in ["boundary", "path"] {
            if let Some(a) = e.get(k).and_then(|p| p.as_arr()) {
                for p in a {
                    if let Some(p) = p.as_arr() {
                        if let (Some(x), Some(y)) = (p.first().and_then(|v| v.as_f64()), p.get(1).and_then(|v| v.as_f64())) {
                            lo[0] = lo[0].min(x);
                            lo[1] = lo[1].min(y);
                        }
                    }
                }
            }
        }
    }
    if !lo[0].is_finite() || !(lo[0].abs() > 1e8 || lo[1].abs() > 1e8) {
        return Value::Null;
    }
    let (dx, dy) = (-lo[0], -lo[1]);
    let shift = |p: &mut Value| {
        if let Some(a) = p.as_arr_mut() {
            if a.len() >= 2 {
                if let (Some(x), Some(y)) = (a[0].as_f64(), a[1].as_f64()) {
                    a[0] = Value::f(build::r3(x + dx));
                    a[1] = Value::f(build::r3(y + dy));
                }
            }
        }
    };
    for e in ctx.pr.elements.values_mut() {
        for k in ["start", "end", "at", "point"] {
            if let Some(p) = e.get_mut(k) {
                shift(p);
            }
        }
        for k in ["boundary", "path"] {
            if let Some(Value::Arr(a)) = e.get_mut(k) {
                for p in a.iter_mut() {
                    shift(p);
                }
            }
        }
    }
    Value::Arr(vec![Value::f(dx), Value::f(dy)])
}

fn reply(ctx: &Ctx, schema: &str, name: &str, path: &str, moved: Value) -> Value {
    let mut counts: BTreeMap<String, u64> = BTreeMap::new();
    for e in ctx.pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        *counts.entry(c).or_insert(0) += 1;
    }
    let mut m = Map::new();
    for (k, v) in counts {
        m.insert(&k, Value::u(v));
    }
    crate::jobj! {
        "elements" => Value::Obj(m),
        "format" => schema,
        "moved" => moved,
        "name" => name,
        "path" => path,
        "skipped" => Value::Arr(ctx.skipped.iter().map(|s| Value::s(s)).collect()),
    }
}

