#!/usr/bin/env python3
"""showtypes.py GEN.py CAT [filter]: convert each generated file with the original; print the
category's types that differ from the default project's (layers' materials by name)."""
import json
import os
import re
import subprocess
import sys
import tempfile
import shutil

gen, cat = sys.argv[1], sys.argv[2]
flt = sys.argv[3] if len(sys.argv) > 3 else None
exe = os.environ.get('EXE', '/workspace/executable')
files = subprocess.run(['python3', gen], capture_output=True, text=True).stdout.split()
d0 = json.loads(re.sub(r'"uid": \d+', '"uid": 0', open('/tmp/ifc-import-agent/default.bimcraft').read()))


def strip(v):
    if isinstance(v, dict):
        return {k: strip(x) for k, x in v.items() if k not in ('id', 'guid')}
    if isinstance(v, list):
        return [strip(x) for x in v]
    return v


for f in files:
    if flt and flt not in f:
        continue
    d = tempfile.mkdtemp()
    shutil.copy(f, d)
    p = subprocess.run([exe, 'convert', os.path.basename(f), 'o.bimcraft'], cwd=d, capture_output=True)
    print('##', os.path.basename(f), p.stderr.decode().strip())
    if p.returncode == 0:
        pr = json.loads(re.sub(r'"uid": \d+', '"uid": 0', open(os.path.join(d, 'o.bimcraft')).read()))
        names = {v['guid']: v['name'] for v in pr['library'].values()}
        t0 = d0['types'].get(cat, {}) if cat != 'runs' else {}
        ts = pr['types'].get(cat, {})
        for k, v in ts.items():
            if k in t0 and strip(t0[k]) == strip(v):
                continue
            s = json.dumps(strip(v))
            s = re.sub(r'"([0-9a-f]{8}-[0-9a-f-]{27})"', lambda m: '"' + names.get(m.group(1), 'G') + '"', s)
            print('   ', k, s)
    shutil.rmtree(d)

