"""A port of mapbox earcut (v2.2.x) for testing hypotheses."""


class Node:
    __slots__ = ('i', 'x', 'y', 'prev', 'next', 'z', 'prevZ', 'nextZ', 'steiner')

    def __init__(self, i, x, y):
        self.i = i
        self.x = x
        self.y = y
        self.prev = None
        self.next = None
        self.z = 0
        self.prevZ = None
        self.nextZ = None
        self.steiner = False


def earcut(data, hole_indices=None, dim=2):
    has_holes = bool(hole_indices)
    outer_len = hole_indices[0] * dim if has_holes else len(data)
    outer = linked_list(data, 0, outer_len, dim, True)
    triangles = []
    if outer is None or outer.next is outer.prev:
        return triangles
    if has_holes:
        outer = eliminate_holes(data, hole_indices, outer, dim)
    min_x = min_y = inv_size = 0
    if len(data) > 80 * dim:
        min_x = max_x = data[0]
        min_y = max_y = data[1]
        for i in range(dim, outer_len, dim):
            x = data[i]
            y = data[i + 1]
            min_x = min(min_x, x)
            min_y = min(min_y, y)
            max_x = max(max_x, x)
            max_y = max(max_y, y)
        inv_size = max(max_x - min_x, max_y - min_y)
        inv_size = 32767 / inv_size if inv_size != 0 else 0
    earcut_linked(outer, triangles, dim, min_x, min_y, inv_size, 0)
    return triangles


def linked_list(data, start, end, dim, clockwise):
    last = None
    if clockwise == (signed_area(data, start, end, dim) > 0):
        for i in range(start, end, dim):
            last = insert_node(i, data[i], data[i + 1], last)
    else:
        for i in range(end - dim, start - 1, -dim):
            last = insert_node(i, data[i], data[i + 1], last)
    if last and equals(last, last.next):
        remove_node(last)
        last = last.next
    return last


def filter_points(start, end=None):
    if start is None:
        return start
    if end is None:
        end = start
    p = start
    while True:
        again = False
        if not p.steiner and (equals(p, p.next) or area(p.prev, p, p.next) == 0):
            remove_node(p)
            p = end = p.prev
            if p is p.next:
                break
            again = True
        else:
            p = p.next
        if not (again or p is not end):
            break
    return end


def earcut_linked(ear, triangles, dim, min_x, min_y, inv_size, pass_):
    if ear is None:
        return
    if not pass_ and inv_size:
        index_curve(ear, min_x, min_y, inv_size)
    stop = ear
    while ear.prev is not ear.next:
        prev = ear.prev
        nxt = ear.next
        if (is_ear_hashed(ear, min_x, min_y, inv_size) if inv_size else is_ear(ear)):
            triangles.append(prev.i // dim)
            triangles.append(ear.i // dim)
            triangles.append(nxt.i // dim)
            remove_node(ear)
            ear = nxt.next
            stop = nxt.next
            continue
        ear = nxt
        if ear is stop:
            if not pass_:
                earcut_linked(filter_points(ear), triangles, dim, min_x, min_y, inv_size, 1)
            elif pass_ == 1:
                ear = cure_local_intersections(filter_points(ear), triangles, dim)
                earcut_linked(ear, triangles, dim, min_x, min_y, inv_size, 2)
            elif pass_ == 2:
                split_earcut(ear, triangles, dim, min_x, min_y, inv_size)
            break


def is_ear(ear):
    a, b, c = ear.prev, ear, ear.next
    if area(a, b, c) >= 0:
        return False
    p = ear.next.next
    while p is not ear.prev:
        if point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and area(p.prev, p, p.next) >= 0:
            return False
        p = p.next
    return True


def is_ear_hashed(ear, min_x, min_y, inv_size):
    a, b, c = ear.prev, ear, ear.next
    if area(a, b, c) >= 0:
        return False
    min_tx = min(a.x, b.x, c.x)
    min_ty = min(a.y, b.y, c.y)
    max_tx = max(a.x, b.x, c.x)
    max_ty = max(a.y, b.y, c.y)
    min_z = z_order(min_tx, min_ty, min_x, min_y, inv_size)
    max_z = z_order(max_tx, max_ty, min_x, min_y, inv_size)
    p = ear.prevZ
    n = ear.nextZ
    while p and p.z >= min_z and n and n.z <= max_z:
        if p is not ear.prev and p is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and area(p.prev, p, p.next) >= 0:
            return False
        p = p.prevZ
        if n is not ear.prev and n is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, n.x, n.y) and area(n.prev, n, n.next) >= 0:
            return False
        n = n.nextZ
    while p and p.z >= min_z:
        if p is not ear.prev and p is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and area(p.prev, p, p.next) >= 0:
            return False
        p = p.prevZ
    while n and n.z <= max_z:
        if n is not ear.prev and n is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, n.x, n.y) and area(n.prev, n, n.next) >= 0:
            return False
        n = n.nextZ
    return True


def cure_local_intersections(start, triangles, dim):
    p = start
    while True:
        a = p.prev
        b = p.next.next
        if not equals(a, b) and intersects(a, p, p.next, b) and locally_inside(a, b) and locally_inside(b, a):
            triangles.append(a.i // dim)
            triangles.append(p.i // dim)
            triangles.append(b.i // dim)
            remove_node(p)
            remove_node(p.next)
            p = start = b
        p = p.next
        if p is start:
            break
    return filter_points(p)


def split_earcut(start, triangles, dim, min_x, min_y, inv_size):
    a = start
    while True:
        b = a.next.next
        while b is not a.prev:
            if a.i != b.i and is_valid_diagonal(a, b):
                c = split_polygon(a, b)
                a = filter_points(a, a.next)
                c = filter_points(c, c.next)
                earcut_linked(a, triangles, dim, min_x, min_y, inv_size, 0)
                earcut_linked(c, triangles, dim, min_x, min_y, inv_size, 0)
                return
            b = b.next
        a = a.next
        if a is start:
            break


def eliminate_holes(data, hole_indices, outer_node, dim):
    queue = []
    n = len(hole_indices)
    for i in range(n):
        start = hole_indices[i] * dim
        end = hole_indices[i + 1] * dim if i < n - 1 else len(data)
        lst = linked_list(data, start, end, dim, False)
        if lst is lst.next:
            lst.steiner = True
        queue.append(get_leftmost(lst))
    queue.sort(key=lambda node: node.x)
    for q in queue:
        outer_node = eliminate_hole(q, outer_node)
    return outer_node


def eliminate_hole(hole, outer_node):
    bridge = find_hole_bridge(hole, outer_node)
    if bridge is None:
        return outer_node
    bridge_reverse = split_polygon(bridge, hole)
    filter_points(bridge_reverse, bridge_reverse.next)
    return filter_points(bridge, bridge.next)


def find_hole_bridge(hole, outer_node):
    p = outer_node
    hx = hole.x
    hy = hole.y
    qx = float('-inf')
    m = None
    while True:
        if hy <= p.y and hy >= p.next.y and p.next.y != p.y:
            x = p.x + (hy - p.y) * (p.next.x - p.x) / (p.next.y - p.y)
            if x <= hx and x > qx:
                qx = x
                m = p if p.x < p.next.x else p.next
                if x == hx:
                    return m
        p = p.next
        if p is outer_node:
            break
    if m is None:
        return None
    stop = m
    mx = m.x
    my = m.y
    tan_min = float('inf')
    p = m
    while True:
        if hx >= p.x and p.x >= mx and hx != p.x and point_in_triangle(hx if hy < my else qx, hy, mx, my, qx if hy < my else hx, hy, p.x, p.y):
            tan = abs(hy - p.y) / (hx - p.x)
            if locally_inside(p, hole) and (tan < tan_min or (tan == tan_min and (p.x > m.x or (p.x == m.x and sector_contains_sector(m, p))))):
                m = p
                tan_min = tan
        p = p.next
        if p is stop:
            break
    return m


def sector_contains_sector(m, p):
    return area(m.prev, m, p.prev) < 0 and area(p.next, m, m.next) < 0


def index_curve(start, min_x, min_y, inv_size):
    p = start
    while True:
        if p.z == 0:
            p.z = z_order(p.x, p.y, min_x, min_y, inv_size)
        p.prevZ = p.prev
        p.nextZ = p.next
        p = p.next
        if p is start:
            break
    p.prevZ.nextZ = None
    p.prevZ = None
    sort_linked(p)


def sort_linked(lst):
    in_size = 1
    while True:
        p = lst
        lst = None
        tail = None
        num_merges = 0
        while p:
            num_merges += 1
            q = p
            p_size = 0
            for i in range(in_size):
                p_size += 1
                q = q.nextZ
                if not q:
                    break
            q_size = in_size
            while p_size > 0 or (q_size > 0 and q):
                if p_size != 0 and (q_size == 0 or not q or p.z <= q.z):
                    e = p
                    p = p.nextZ
                    p_size -= 1
                else:
                    e = q
                    q = q.nextZ
                    q_size -= 1
                if tail:
                    tail.nextZ = e
                else:
                    lst = e
                e.prevZ = tail
                tail = e
            p = q
        tail.nextZ = None
        in_size *= 2
        if num_merges <= 1:
            break
    return lst


def z_order(x, y, min_x, min_y, inv_size):
    x = int((x - min_x) * inv_size)
    y = int((y - min_y) * inv_size)
    x = (x | (x << 8)) & 0x00FF00FF
    x = (x | (x << 4)) & 0x0F0F0F0F
    x = (x | (x << 2)) & 0x33333333
    x = (x | (x << 1)) & 0x55555555
    y = (y | (y << 8)) & 0x00FF00FF
    y = (y | (y << 4)) & 0x0F0F0F0F
    y = (y | (y << 2)) & 0x33333333
    y = (y | (y << 1)) & 0x55555555
    return x | (y << 1)


def get_leftmost(start):
    p = start
    leftmost = start
    while True:
        if p.x < leftmost.x or (p.x == leftmost.x and p.y < leftmost.y):
            leftmost = p
        p = p.next
        if p is start:
            break
    return leftmost


def point_in_triangle(ax, ay, bx, by, cx, cy, px, py):
    return ((cx - px) * (ay - py) >= (ax - px) * (cy - py) and
            (ax - px) * (by - py) >= (bx - px) * (ay - py) and
            (bx - px) * (cy - py) >= (cx - px) * (by - py))


def is_valid_diagonal(a, b):
    return (a.next.i != b.i and a.prev.i != b.i and not intersects_polygon(a, b) and
            (locally_inside(a, b) and locally_inside(b, a) and middle_inside(a, b) and
             (area(a.prev, a, b.prev) or area(a, b.prev, b)) or
             equals(a, b) and area(a.prev, a, a.next) > 0 and area(b.prev, b, b.next) > 0))


def area(p, q, r):
    return (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)


def equals(p1, p2):
    return p1.x == p2.x and p1.y == p2.y


def intersects(p1, q1, p2, q2):
    o1 = sign(area(p1, q1, p2))
    o2 = sign(area(p1, q1, q2))
    o3 = sign(area(p2, q2, p1))
    o4 = sign(area(p2, q2, q1))
    if o1 != o2 and o3 != o4:
        return True
    if o1 == 0 and on_segment(p1, p2, q1):
        return True
    if o2 == 0 and on_segment(p1, q2, q1):
        return True
    if o3 == 0 and on_segment(p2, p1, q2):
        return True
    if o4 == 0 and on_segment(p2, q1, q2):
        return True
    return False


def on_segment(p, q, r):
    return q.x <= max(p.x, r.x) and q.x >= min(p.x, r.x) and q.y <= max(p.y, r.y) and q.y >= min(p.y, r.y)


def sign(num):
    return 1 if num > 0 else (-1 if num < 0 else 0)


def intersects_polygon(a, b):
    p = a
    while True:
        if p.i != a.i and p.next.i != a.i and p.i != b.i and p.next.i != b.i and intersects(p, p.next, a, b):
            return True
        p = p.next
        if p is a:
            break
    return False


def locally_inside(a, b):
    if area(a.prev, a, a.next) < 0:
        return area(a, b, a.next) >= 0 and area(a, a.prev, b) >= 0
    return area(a, b, a.prev) < 0 or area(a, a.next, b) < 0


def middle_inside(a, b):
    p = a
    inside = False
    px = (a.x + b.x) / 2
    py = (a.y + b.y) / 2
    while True:
        if ((p.y > py) != (p.next.y > py)) and p.next.y != p.y and (px < (p.next.x - p.x) * (py - p.y) / (p.next.y - p.y) + p.x):
            inside = not inside
        p = p.next
        if p is a:
            break
    return inside


def split_polygon(a, b):
    a2 = Node(a.i, a.x, a.y)
    b2 = Node(b.i, b.x, b.y)
    an = a.next
    bp = b.prev
    a.next = b
    b.prev = a
    a2.next = an
    an.prev = a2
    b2.next = a2
    a2.prev = b2
    bp.next = b2
    b2.prev = bp
    return b2


def insert_node(i, x, y, last):
    p = Node(i, x, y)
    if last is None:
        p.prev = p
        p.next = p
    else:
        p.next = last.next
        p.prev = last
        last.next.prev = p
        last.next = p
    return p


def remove_node(p):
    p.next.prev = p.prev
    p.prev.next = p.next
    if p.prevZ:
        p.prevZ.nextZ = p.nextZ
    if p.nextZ:
        p.nextZ.prevZ = p.prevZ


def signed_area(data, start, end, dim):
    s = 0
    j = end - dim
    for i in range(start, end, dim):
        s += (data[j] - data[i]) * (data[i + 1] + data[j + 1])
        j = i
    return s

"""A port of mapbox earcut (v2.2.x) for testing hypotheses."""


class Node:
    __slots__ = ('i', 'x', 'y', 'prev', 'next', 'z', 'prevZ', 'nextZ', 'steiner')

    def __init__(self, i, x, y):
        self.i = i
        self.x = x
        self.y = y
        self.prev = None
        self.next = None
        self.z = 0
        self.prevZ = None
        self.nextZ = None
        self.steiner = False


def earcut(data, hole_indices=None, dim=2):
    has_holes = bool(hole_indices)
    outer_len = hole_indices[0] * dim if has_holes else len(data)
    outer = linked_list(data, 0, outer_len, dim, True)
    triangles = []
    if outer is None or outer.next is outer.prev:
        return triangles
    if has_holes:
        outer = eliminate_holes(data, hole_indices, outer, dim)
    min_x = min_y = inv_size = 0
    if len(data) > 80 * dim:
        min_x = max_x = data[0]
        min_y = max_y = data[1]
        for i in range(dim, outer_len, dim):
            x = data[i]
            y = data[i + 1]
            min_x = min(min_x, x)
            min_y = min(min_y, y)
            max_x = max(max_x, x)
            max_y = max(max_y, y)
        inv_size = max(max_x - min_x, max_y - min_y)
        inv_size = 32767 / inv_size if inv_size != 0 else 0
    earcut_linked(outer, triangles, dim, min_x, min_y, inv_size, 0)
    return triangles


def linked_list(data, start, end, dim, clockwise):
    last = None
    if clockwise == (signed_area(data, start, end, dim) > 0):
        for i in range(start, end, dim):
            last = insert_node(i, data[i], data[i + 1], last)
    else:
        for i in range(end - dim, start - 1, -dim):
            last = insert_node(i, data[i], data[i + 1], last)
    if last and equals(last, last.next):
        remove_node(last)
        last = last.next
    return last


def filter_points(start, end=None):
    if start is None:
        return start
    if end is None:
        end = start
    p = start
    while True:
        again = False
        if not p.steiner and (equals(p, p.next) or area(p.prev, p, p.next) == 0):
            remove_node(p)
            p = end = p.prev
            if p is p.next:
                break
            again = True
        else:
            p = p.next
        if not (again or p is not end):
            break
    return end


def earcut_linked(ear, triangles, dim, min_x, min_y, inv_size, pass_):
    if ear is None:
        return
    if not pass_ and inv_size:
        index_curve(ear, min_x, min_y, inv_size)
    stop = ear
    while ear.prev is not ear.next:
        prev = ear.prev
        nxt = ear.next
        if (is_ear_hashed(ear, min_x, min_y, inv_size) if inv_size else is_ear(ear)):
            triangles.append(prev.i // dim)
            triangles.append(ear.i // dim)
            triangles.append(nxt.i // dim)
            remove_node(ear)
            ear = nxt.next
            stop = nxt.next
            continue
        ear = nxt
        if ear is stop:
            if not pass_:
                earcut_linked(filter_points(ear), triangles, dim, min_x, min_y, inv_size, 1)
            elif pass_ == 1:
                ear = cure_local_intersections(filter_points(ear), triangles, dim)
                earcut_linked(ear, triangles, dim, min_x, min_y, inv_size, 2)
            elif pass_ == 2:
                split_earcut(ear, triangles, dim, min_x, min_y, inv_size)
            break


def is_ear(ear):
    a, b, c = ear.prev, ear, ear.next
    if area(a, b, c) >= 0:
        return False
    p = ear.next.next
    while p is not ear.prev:
        if point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and area(p.prev, p, p.next) >= 0:
            return False
        p = p.next
    return True


def is_ear_hashed(ear, min_x, min_y, inv_size):
    a, b, c = ear.prev, ear, ear.next
    if area(a, b, c) >= 0:
        return False
    min_tx = min(a.x, b.x, c.x)
    min_ty = min(a.y, b.y, c.y)
    max_tx = max(a.x, b.x, c.x)
    max_ty = max(a.y, b.y, c.y)
    min_z = z_order(min_tx, min_ty, min_x, min_y, inv_size)
    max_z = z_order(max_tx, max_ty, min_x, min_y, inv_size)
    p = ear.prevZ
    n = ear.nextZ
    while p and p.z >= min_z and n and n.z <= max_z:
        if p is not ear.prev and p is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and area(p.prev, p, p.next) >= 0:
            return False
        p = p.prevZ
        if n is not ear.prev and n is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, n.x, n.y) and area(n.prev, n, n.next) >= 0:
            return False
        n = n.nextZ
    while p and p.z >= min_z:
        if p is not ear.prev and p is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and area(p.prev, p, p.next) >= 0:
            return False
        p = p.prevZ
    while n and n.z <= max_z:
        if n is not ear.prev and n is not ear.next and point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, n.x, n.y) and area(n.prev, n, n.next) >= 0:
            return False
        n = n.nextZ
    return True


def cure_local_intersections(start, triangles, dim):
    p = start
    while True:
        a = p.prev
        b = p.next.next
        if not equals(a, b) and intersects(a, p, p.next, b) and locally_inside(a, b) and locally_inside(b, a):
            triangles.append(a.i // dim)
            triangles.append(p.i // dim)
            triangles.append(b.i // dim)
            remove_node(p)
            remove_node(p.next)
            p = start = b
        p = p.next
        if p is start:
            break
    return filter_points(p)


def split_earcut(start, triangles, dim, min_x, min_y, inv_size):
    a = start
    while True:
        b = a.next.next
        while b is not a.prev:
            if a.i != b.i and is_valid_diagonal(a, b):
                c = split_polygon(a, b)
                a = filter_points(a, a.next)
                c = filter_points(c, c.next)
                earcut_linked(a, triangles, dim, min_x, min_y, inv_size, 0)
                earcut_linked(c, triangles, dim, min_x, min_y, inv_size, 0)
                return
            b = b.next
        a = a.next
        if a is start:
            break


def eliminate_holes(data, hole_indices, outer_node, dim):
    queue = []
    n = len(hole_indices)
    for i in range(n):
        start = hole_indices[i] * dim
        end = hole_indices[i + 1] * dim if i < n - 1 else len(data)
        lst = linked_list(data, start, end, dim, False)
        if lst is lst.next:
            lst.steiner = True
        queue.append(get_leftmost(lst))
    queue.sort(key=lambda node: node.x)
    for q in queue:
        outer_node = eliminate_hole(q, outer_node)
    return outer_node


def eliminate_hole(hole, outer_node):
    bridge = find_hole_bridge(hole, outer_node)
    if bridge is None:
        return outer_node
    bridge_reverse = split_polygon(bridge, hole)
    filter_points(bridge_reverse, bridge_reverse.next)
    return filter_points(bridge, bridge.next)


def find_hole_bridge(hole, outer_node):
    p = outer_node
    hx = hole.x
    hy = hole.y
    qx = float('-inf')
    m = None
    while True:
        if hy <= p.y and hy >= p.next.y and p.next.y != p.y:
            x = p.x + (hy - p.y) * (p.next.x - p.x) / (p.next.y - p.y)
            if x <= hx and x > qx:
                qx = x
                m = p if p.x < p.next.x else p.next
                if x == hx:
                    return m
        p = p.next
        if p is outer_node:
            break
    if m is None:
        return None
    stop = m
    mx = m.x
    my = m.y
    tan_min = float('inf')
    p = m
    while True:
        if hx >= p.x and p.x >= mx and hx != p.x and point_in_triangle(hx if hy < my else qx, hy, mx, my, qx if hy < my else hx, hy, p.x, p.y):
            tan = abs(hy - p.y) / (hx - p.x)
            if locally_inside(p, hole) and (tan < tan_min or (tan == tan_min and (p.x > m.x or (p.x == m.x and sector_contains_sector(m, p))))):
                m = p
                tan_min = tan
        p = p.next
        if p is stop:
            break
    return m


def sector_contains_sector(m, p):
    return area(m.prev, m, p.prev) < 0 and area(p.next, m, m.next) < 0


def index_curve(start, min_x, min_y, inv_size):
    p = start
    while True:
        if p.z == 0:
            p.z = z_order(p.x, p.y, min_x, min_y, inv_size)
        p.prevZ = p.prev
        p.nextZ = p.next
        p = p.next
        if p is start:
            break
    p.prevZ.nextZ = None
    p.prevZ = None
    sort_linked(p)


def sort_linked(lst):
    in_size = 1
    while True:
        p = lst
        lst = None
        tail = None
        num_merges = 0
        while p:
            num_merges += 1
            q = p
            p_size = 0
            for i in range(in_size):
                p_size += 1
                q = q.nextZ
                if not q:
                    break
            q_size = in_size
            while p_size > 0 or (q_size > 0 and q):
                if p_size != 0 and (q_size == 0 or not q or p.z <= q.z):
                    e = p
                    p = p.nextZ
                    p_size -= 1
                else:
                    e = q
                    q = q.nextZ
                    q_size -= 1
                if tail:
                    tail.nextZ = e
                else:
                    lst = e
                e.prevZ = tail
                tail = e
            p = q
        tail.nextZ = None
        in_size *= 2
        if num_merges <= 1:
            break
    return lst


def z_order(x, y, min_x, min_y, inv_size):
    x = int((x - min_x) * inv_size)
    y = int((y - min_y) * inv_size)
    x = (x | (x << 8)) & 0x00FF00FF
    x = (x | (x << 4)) & 0x0F0F0F0F
    x = (x | (x << 2)) & 0x33333333
    x = (x | (x << 1)) & 0x55555555
    y = (y | (y << 8)) & 0x00FF00FF
    y = (y | (y << 4)) & 0x0F0F0F0F
    y = (y | (y << 2)) & 0x33333333
    y = (y | (y << 1)) & 0x55555555
    return x | (y << 1)


