            (locally_inside(a, b) and locally_inside(b, a) and middle_inside(a, b) and
             (area(a.prev, a, b.prev) or area(a, b.prev, b)) or
             equals(a, b) and area(a.prev, a, a.next) > 0 and area(b.prev, b, b.next) > 0))


def area(p, q, r):
    return (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)


def equals(p1, p2):
    return p1.x == p2.x and p1.y == p2.y


def intersects(p1, q1, p2, q2):
    o1 = sign(area(p1, q1, p2))
    o2 = sign(area(p1, q1, q2))
    o3 = sign(area(p2, q2, p1))
    o4 = sign(area(p2, q2, q1))
    if o1 != o2 and o3 != o4:
        return True
    if o1 == 0 and on_segment(p1, p2, q1):
        return True
    if o2 == 0 and on_segment(p1, q2, q1):
        return True
    if o3 == 0 and on_segment(p2, p1, q2):
        return True
    if o4 == 0 and on_segment(p2, q1, q2):
        return True
    return False


def on_segment(p, q, r):
    return q.x <= max(p.x, r.x) and q.x >= min(p.x, r.x) and q.y <= max(p.y, r.y) and q.y >= min(p.y, r.y)


def sign(num):
    return 1 if num > 0 else (-1 if num < 0 else 0)


def intersects_polygon(a, b):
