from roompt2 import cases


def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def inside(p, a, b, c):
    # strictly or on edge?
    d1 = cross(a, b, p)
    d2 = cross(b, c, p)
    d3 = cross(c, a, p)
    return d1 >= 0 and d2 >= 0 and d3 >= 0


def signed(pts):
    return sum(pts[i][0] * pts[(i + 1) % len(pts)][1] - pts[(i + 1) % len(pts)][0] * pts[i][1] for i in range(len(pts))) / 2


def earclip(pts, restart):
    v = list(pts)
    tris = []
    i = 0
    guard = 0
    while len(v) > 3 and guard < 10000:
        guard += 1
        n = len(v)
        found = False
        for k in range(n):
            j = (i + k) % n
            a, b, c = v[(j - 1) % n], v[j], v[(j + 1) % n]
            if cross(a, b, c) <= 0:
                continue
            ok = True
            for q in v:
                if q in (a, b, c):
                    continue
                if inside(q, a, b, c):
                    ok = False
                    break
            if ok:
                tris.append((a, b, c))
                del v[j]
                i = 0 if restart else j % len(v)
                found = True
                break
        if not found:
            break
    if len(v) == 3:
        tris.append(tuple(v))
    return tris


def area(t):
    (a, b, c) = t
    return abs(cross(a, b, c)) / 2


def cen(t):
    return (round(sum(p[0] for p in t) / 3, 3), round(sum(p[1] for p in t) / 3, 3))


def canon(pts, how):
    p = list(pts)
    if signed(p) < 0:
        p = p[::-1]
    if how == 'miny':
        k = min(range(len(p)), key=lambda i: (p[i][1], p[i][0]))
    elif how == 'minx':
        k = min(range(len(p)), key=lambda i: (p[i][0], p[i][1]))
    else:
        k = 0
    return p[k:] + p[:k]


for how in ('none', 'miny', 'minx'):
    for restart in (True, False):
        ok = 0
        bad = []
        for k, (pts, want) in cases.items():
            P = canon(pts, how)
            ts = earclip(P, restart)
            mx = max(area(t) for t in ts)
            cands = [cen(t) for t in ts if abs(area(t) - mx) < 1e-6 * max(1, mx)]
            if cands[-1] == want:
                ok += 1
            else:
                bad.append((k, cands, want))
        print(how, 'restart' if restart else 'continue', ok, '/', len(cases), [b[0] for b in bad])

