"""A minimal IFC (STEP) reader for analysing BIMCraft exports in Python."""
import re
import math


def parse_args(s):
    out = []
    i = 0
    n = len(s)

    def val(i):
        while s[i] in ' \n\r\t':
            i += 1
        c = s[i]
        if c == "'":
            j = i + 1
            buf = ''
            while True:
                k = s.index("'", j)
                buf += s[j:k]
                if k + 1 < n and s[k + 1] == "'":
                    buf += "'"
                    j = k + 2
                else:
                    return buf, k + 1
        if c == '(':
            lst = []
            i += 1
            while s[i] in ' \n':
                i += 1
            if s[i] == ')':
                return lst, i + 1
            while True:
                v, i = val(i)
                lst.append(v)
                while s[i] in ' \n':
                    i += 1
                if s[i] == ',':
                    i += 1
                    continue
                if s[i] == ')':
                    return lst, i + 1
        if c == '#':
            m = re.match(r'#(\d+)', s[i:])
            return ('ref', int(m.group(1))), i + len(m.group(0))
        if c == '$':
            return None, i + 1
        if c == '*':
            return '*', i + 1
        if c == '.':
            k = s.index('.', i + 1)
            return ('enum', s[i + 1:k]), k + 1
        m = re.match(r'[-+0-9.eE]+', s[i:])
        if m and (c.isdigit() or c in '+-'):
            t = m.group(0)
            return float(t), i + len(t)
        m = re.match(r'[A-Za-z0-9_]+', s[i:])
        name = m.group(0)
        i += len(name)
        v, i = val(i)
        return ('typed', name.upper(), v), i
    v, _ = val(0)
    return v


def read(path):
    text = open(path, encoding='utf-8', errors='replace').read()
    data = text[text.index('DATA;') + 5:]
    ents = {}
    for m in re.finditer(r'#(\d+)\s*=\s*([A-Za-z0-9_]+)\s*(\(.*?\));\s*$', data, re.M | re.S):
        ents[int(m.group(1))] = (m.group(2).upper(), parse_args(m.group(3)))
    return ents


