/// An edge split at the corners that lie on it (in space, within a hundredth of a millimetre).
fn split_edge(a: V3, b: V3, corners: &[V3]) -> Vec<(V3, V3)> {
    let d = geom::sub(b, a);
    let l2 = geom::dot(d, d);
    let mut on: Vec<(f64, V3)> = Vec::new();
    if l2 > 0.0 {
        for p in corners {
            let t = geom::dot(geom::sub(*p, a), d) / l2;
            if t <= 1e-9 || t >= 1.0 - 1e-9 {
                continue;
            }
            let q = geom::add(a, geom::mul(d, t));
            if geom::norm(geom::sub(*p, q)) < 0.01 {
                on.push((t, *p));
            }
        }
    }
    if on.is_empty() {
        return vec![(a, b)];
    }
    on.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
    let mut out = Vec::new();
    let mut cur = a;
    for (_, p) in on {
        out.push((cur, p));
        cur = p;
    }
    out.push((cur, b));
    out
}

