153	        m.insert("slope", Value::f(0.0));
154	        m.insert("overhang", Value::f(0.0));
155	        m.insert("offset", Value::f(r3(t.z_bottom - lev)));
156	        if !holes.is_empty() {
157	            m.insert("openings", Value::Arr(holes.iter().map(|h| pts_value(h)).collect()));
158	        }
159	        add_roof(ctx, id, m, solids);
