171	        }
172	        let tname = roof_type(ctx, id, &tname, thickness);
173	        let outer = canonical(&t.outer, false);
174	        let holes: Vec<Vec<V2>> = t.holes.iter().map(|h| canonical(h, true)).collect();
175	        // which of the outline's edges are eaves: the roof rises from them
176	        let mut edges: Vec<(V2, V2)> = Vec::new();
177	        let ring_edges = |l: &Vec<V2>| -> Vec<(V2, V2)> { (0..l.len()).map(|i| (l[i], l[(i + 1) % l.len()])).collect() };
