202	        m.insert("boundary", pts_value(&outer));
203	        if !courts.is_empty() {
204	            m.insert("courtyards", Value::Arr(courts.iter().map(|h| pts_value(h)).collect()));
205	        }
206	        m.insert("slope", Value::f(r2(s)));
207	        m.insert("overhang", Value::f(overhang));
208	        if !gables.is_empty() {
