/// How the roof along an edge of its outline climbs from it: the cosine between the uphill of
/// the face along the edge and the edge's inward normal (1: it rises from the edge, an eave;
/// -1: it rises to it), if a sloped face lies along it.
fn edge_gradient(ups: &[(Vec<V3>, (V3, f64))], e: (V2, V2)) -> Option<f64> {
    let d = [e.1[0] - e.0[0], e.1[1] - e.0[1]];
    let l = (d[0] * d[0] + d[1] * d[1]).sqrt();
    if l == 0.0 {
        return None;
    }
    let inward = [-d[1] / l, d[0] / l];
    let mid = [(e.0[0] + e.1[0]) / 2.0, (e.0[1] + e.1[1]) / 2.0];
    for (pts, (n, _)) in ups {
        // the face has an edge on this one
        let k = pts.len();
        let mut on = false;
        for i in 0..k {
            let (a, b) = (pts[i], pts[(i + 1) % k]);
            if seg_has([a[0], a[1]], [b[0], b[1]], mid) {
                on = true;
                break;
            }
        }
        if !on {
            continue;
        }
        let h = (n[0] * n[0] + n[1] * n[1]).sqrt();
        if h < 1e-9 {
            return None;
        }
        let g = [-n[0] / h, -n[1] / h];
        return Some(g[0] * inward[0] + g[1] * inward[1]);
    }
    None
}

/// Whether the roof rises from an edge of its outline: an eave, not a gable.
fn is_eave(ups: &[(Vec<V3>, (V3, f64))], e: (V2, V2)) -> bool {
    edge_gradient(ups, e).map(|x| x > 0.5).unwrap_or(false)
}

fn seg_has(a: V2, b: V2, p: V2) -> bool {
    let d = [b[0] - a[0], b[1] - a[1]];
    let l2 = d[0] * d[0] + d[1] * d[1];
    if l2 == 0.0 {
        return false;
    }
    let t = ((p[0] - a[0]) * d[0] + (p[1] - a[1]) * d[1]) / l2;
    if t < -1e-9 || t > 1.0 + 1e-9 {
        return false;
    }
    let q = [a[0] + d[0] * t, a[1] + d[1] * t];
    ((p[0] - q[0]).powi(2) + (p[1] - q[1]).powi(2)).sqrt() < 0.01
}

struct Ext {
    a: V2,
    b: V2,
    profile: Vec<V2>,
    width: f64,
    z0: f64,
}

/// A roof that is one profile swept across: every face looking down shares one level
/// direction; its profile the undersides' section along the line square to it, its outline
/// the rectangle the profile sweeps.
fn extrusion(t: &super::import_slabs::Top, ups: &[(Vec<V3>, (V3, f64))], downs: &[(Vec<V3>, (V3, f64))]) -> Option<Result<Ext, &'static str>> {
    let _ = ups;
    let ns: Vec<V3> = downs.iter().map(|d| d.1 .0).filter(|n| n[2] < -1e-6).collect();
    if ns.is_empty() {
        return None;
    }
    // the sweep: level, square to every normal
    let mut sweep: Option<V2> = None;
    for n in &ns {
        let h = (n[0] * n[0] + n[1] * n[1]).sqrt();
        if h > 1e-6 {
            sweep = Some([-n[1] / h, n[0] / h]);
            break;
        }
    }
    let sw = sweep?;
    for n in &ns {
        let h = (n[0] * n[0] + n[1] * n[1]).sqrt();
        if (n[0] * sw[0] + n[1] * sw[1]).abs() > 1e-6 * h.max(1e-9) * 1e3 {
            return None;
        }
    }
    // the profile's axis: square to the sweep, pointing east (or north)
    let mut u = [sw[1], -sw[0]];
    if u[0] < -1e-12 || (u[0].abs() <= 1e-12 && u[1] < 0.0) {
        u = [-u[0], -u[1]];
    }
    let left = [-u[1], u[0]];
    // the undersides' points in (along u, height), and how far they spread across
    let mut segs: Vec<(f64, f64, f64, f64)> = Vec::new();
    let (mut c0, mut c1) = (f64::INFINITY, f64::NEG_INFINITY);
    let (mut u0, mut u1) = (f64::INFINITY, f64::NEG_INFINITY);
    let mut z0 = f64::INFINITY;
    for (pts, (n, _)) in downs {
        if n[2] >= -1e-6 {
            continue;
        }
        let (mut a, mut b) = ((f64::INFINITY, 0.0), (f64::NEG_INFINITY, 0.0));
        for p in pts {
            let pu = p[0] * u[0] + p[1] * u[1];
            let pc = p[0] * left[0] + p[1] * left[1];
            c0 = c0.min(pc);
            c1 = c1.max(pc);
            u0 = u0.min(pu);
            u1 = u1.max(pu);
            z0 = z0.min(p[2]);
            if pu < a.0 {
                a = (pu, p[2]);
            }
            if pu > b.0 {
                b = (pu, p[2]);
            }
        }
        segs.push((a.0, a.1, b.0, b.1));
    }
    segs.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
    let mut profile: Vec<V2> = Vec::new();
    for s in &segs {
        let p = [s.0 - u0, s.1 - z0];
        if profile.last().map(|l: &V2| (l[0] - p[0]).abs() > 0.5 || (l[1] - p[1]).abs() > 0.5).unwrap_or(true) {
            profile.push(p);
        }
        let q = [s.2 - u0, s.3 - z0];
        profile.push(q);
    }
    let a = [u[0] * u0 + left[0] * c0, u[1] * u0 + left[1] * c0];
    let b = [u[0] * u1 + left[0] * c0, u[1] * u1 + left[1] * c0];
    // the outline must be the rectangle the profile sweeps
    let rect = [a, b, [b[0] + left[0] * (c1 - c0), b[1] + left[1] * (c1 - c0)], [a[0] + left[0] * (c1 - c0), a[1] + left[1] * (c1 - c0)]];
    let outline = super::import_slabs::simplify(&t.outer);
    let ok = t.holes.is_empty()
        && outline.len() == 4
        && outline.iter().all(|p| rect.iter().any(|q| (p[0] - q[0]).abs() < 0.5 && (p[1] - q[1]).abs() < 0.5));
    if !ok {
        return Some(Err("its outline isn't the rectangle its profile sweeps"));
    }
    Some(Ok(Ext { a, b, profile, width: c1 - c0, z0 }))
}

/// How the roof along an edge of its outline climbs from it: the cosine between the uphill of
/// the face along the edge and the edge's inward normal (1: it rises from the edge, an eave;
/// -1: it rises to it), if a sloped face lies along it.
fn edge_gradient(ups: &[(Vec<V3>, (V3, f64))], e: (V2, V2)) -> Option<f64> {
    let d = [e.1[0] - e.0[0], e.1[1] - e.0[1]];
    let l = (d[0] * d[0] + d[1] * d[1]).sqrt();
    if l == 0.0 {
        return None;
    }
    let inward = [-d[1] / l, d[0] / l];
    let mid = [(e.0[0] + e.1[0]) / 2.0, (e.0[1] + e.1[1]) / 2.0];
    for (pts, (n, _)) in ups {
        // the face has an edge on this one
        let k = pts.len();
        let mut on = false;
        for i in 0..k {
            let (a, b) = (pts[i], pts[(i + 1) % k]);
            if seg_has([a[0], a[1]], [b[0], b[1]], mid) {
                on = true;
                break;
            }
        }
        if !on {
            continue;
        }
        let h = (n[0] * n[0] + n[1] * n[1]).sqrt();
        if h < 1e-9 {
            return None;
        }
        let g = [-n[0] / h, -n[1] / h];
        return Some(g[0] * inward[0] + g[1] * inward[1]);
    }
    None
}

/// Whether the roof rises from an edge of its outline: an eave, not a gable.
fn is_eave(ups: &[(Vec<V3>, (V3, f64))], e: (V2, V2)) -> bool {
    edge_gradient(ups, e).map(|x| x > 0.5).unwrap_or(false)
}

fn seg_has(a: V2, b: V2, p: V2) -> bool {
    let d = [b[0] - a[0], b[1] - a[1]];
    let l2 = d[0] * d[0] + d[1] * d[1];
    if l2 == 0.0 {
        return false;
    }
    let t = ((p[0] - a[0]) * d[0] + (p[1] - a[1]) * d[1]) / l2;
    if t < -1e-9 || t > 1.0 + 1e-9 {
        return false;
    }
    let q = [a[0] + d[0] * t, a[1] + d[1] * t];
    ((p[0] - q[0]).powi(2) + (p[1] - q[1]).powi(2)).sqrt() < 0.01
}

struct Ext {
    a: V2,
    b: V2,
    profile: Vec<V2>,
    width: f64,
    z0: f64,
}

/// A roof that is one profile swept across: every face looking down shares one level
/// direction; its profile the undersides' section along the line square to it, its outline
/// the rectangle the profile sweeps.
fn extrusion(t: &super::import_slabs::Top, ups: &[(Vec<V3>, (V3, f64))], downs: &[(Vec<V3>, (V3, f64))]) -> Option<Result<Ext, &'static str>> {
    let _ = ups;
    let ns: Vec<V3> = downs.iter().map(|d| d.1 .0).filter(|n| n[2] < -1e-6).collect();
    if ns.is_empty() {
        return None;
    }
    // the sweep: level, square to every normal
    let mut sweep: Option<V2> = None;
    for n in &ns {
        let h = (n[0] * n[0] + n[1] * n[1]).sqrt();
        if h > 1e-6 {
            sweep = Some([-n[1] / h, n[0] / h]);
            break;
        }
    }
    let sw = sweep?;
    for n in &ns {
        let h = (n[0] * n[0] + n[1] * n[1]).sqrt();
        if (n[0] * sw[0] + n[1] * sw[1]).abs() > 1e-6 * h.max(1e-9) * 1e3 {
            return None;
        }
    }
    // the profile's axis: square to the sweep, pointing east (or north)
    let mut u = [sw[1], -sw[0]];
    if u[0] < -1e-12 || (u[0].abs() <= 1e-12 && u[1] < 0.0) {
        u = [-u[0], -u[1]];
    }
    let left = [-u[1], u[0]];
    // the undersides' points in (along u, height), and how far they spread across
    let mut segs: Vec<(f64, f64, f64, f64)> = Vec::new();
    let (mut c0, mut c1) = (f64::INFINITY, f64::NEG_INFINITY);
    let (mut u0, mut u1) = (f64::INFINITY, f64::NEG_INFINITY);
    let mut z0 = f64::INFINITY;
    for (pts, (n, _)) in downs {
        if n[2] >= -1e-6 {
            continue;
        }
        let (mut a, mut b) = ((f64::INFINITY, 0.0), (f64::NEG_INFINITY, 0.0));
        for p in pts {
            let pu = p[0] * u[0] + p[1] * u[1];
            let pc = p[0] * left[0] + p[1] * left[1];
            c0 = c0.min(pc);
            c1 = c1.max(pc);
            u0 = u0.min(pu);
            u1 = u1.max(pu);
            z0 = z0.min(p[2]);
            if pu < a.0 {
                a = (pu, p[2]);
            }
            if pu > b.0 {
                b = (pu, p[2]);
            }
        }
        segs.push((a.0, a.1, b.0, b.1));
    }
    segs.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
    let mut profile: Vec<V2> = Vec::new();
    for s in &segs {
        let p = [s.0 - u0, s.1 - z0];
        if profile.last().map(|l: &V2| (l[0] - p[0]).abs() > 0.5 || (l[1] - p[1]).abs() > 0.5).unwrap_or(true) {
            profile.push(p);
        }
        let q = [s.2 - u0, s.3 - z0];
        profile.push(q);
    }
    let a = [u[0] * u0 + left[0] * c0, u[1] * u0 + left[1] * c0];
    let b = [u[0] * u1 + left[0] * c0, u[1] * u1 + left[1] * c0];
    // the outline must be the rectangle the profile sweeps
    let rect = [a, b, [b[0] + left[0] * (c1 - c0), b[1] + left[1] * (c1 - c0)], [a[0] + left[0] * (c1 - c0), a[1] + left[1] * (c1 - c0)]];
    let outline = super::import_slabs::simplify(&t.outer);
    let ok = t.holes.is_empty()
        && outline.len() == 4
        && outline.iter().all(|p| rect.iter().any(|q| (p[0] - q[0]).abs() < 0.5 && (p[1] - q[1]).abs() < 0.5));
    if !ok {
        return Some(Err("its outline isn't the rectangle its profile sweeps"));
    }
    Some(Ok(Ext { a, b, profile, width: c1 - c0, z0 }))
}

