let mid = [(w.start[0] + w.end[0]) / 2.0, (w.start[1] + w.end[1]) / 2.0];
let mut found: Option<(f64, String)> = None;
let mut any: Option<String> = None;
for (ent, _, g) in &ctx.roofs.roofs {
