        Some(s) => s,
        None => continue,
    };
    let mut downs: Vec<(Vec<V3>, (V3, f64))> = Vec::new();
    for s in solids {
        for f in &s.faces {
            if f.outer.len() >= 3 {
                let pl = plane(&f.outer);
                if pl.0[2] < -1e-6 {
                    downs.push((f.outer.clone(), pl));
                }
            }
        }
    }
    if let Some(z) = under_z(&downs, mid) {
        if any.is_none() {
            any = Some(g.clone());
        }
        if z >= w.z0 - 1.0 && found.as_ref().map(|(b, _)| z < *b).unwrap_or(true) {
            found = Some((z, g.clone()));
        }
    }
}
let found = found.map(|(_, g)| g).or(any);

