import sys
sys.path.insert(0, '/tmp/ifc-import-agent')
from ifcread import read

ents = read(sys.argv[1])
par = {}
for i, (n, a) in ents.items():
    if n == 'IFCRELAGGREGATES':
        for c in a[5]:
            par[c[1]] = a[4][1]


def pts_of_brep(bid):
    n, a = ents[bid]
    sh = ents[a[0][1]][1][0]
    out = []
    for f in sh:
        fb = ents[f[1]][1][0]
        for b in fb:
            lp = ents[ents[b[1]][1][0][1]][1][0]
            for p in lp:
                out.append(tuple(ents[p[1]][1][0]))
    return out


def placement_z(lp):
    z = 0.0
    while lp:
        n, a = ents[lp]
        ax = ents[a[1][1]][1]
        z += ents[ax[0][1]][1][0][2] if len(ents[ax[0][1]][1][0]) > 2 else 0
        lp = a[0][1] if a[0] else None
    return z


for i, (n, a) in sorted(ents.items()):
    if n != 'IFCRAILING':
        continue
    pds = ents[a[6][1]][1]
    axis = None
    zs = []
    for rep in pds[2]:
        rn, ra = ents[rep[1]]
        if ra[1] == 'Axis':
            pl = ents[ra[3][0][1]][1][0]
            axis = [tuple(ents[p[1]][1][0]) for p in pl]
        else:
            for it in ra[3]:
                if ents[it[1]][0] == 'IFCFACETEDBREP':
                    zs += [p[2] for p in pts_of_brep(it[1])]
    host = par.get(i)
    print(i, a[2], 'host', host, ents[host][0] if host else None, 'pz', placement_z(a[5][1]))
    print('   axis', axis)
    print('   body z', min(zs) if zs else None, max(zs) if zs else None)

