#!/usr/bin/env python3
"""fam.py project.bimcraft [family...]: show families changed or new vs the default project, compactly:
forms with material names and triangle counts, the first triangles, and the library guids they hold."""
import json
import re
import sys

d0 = json.load(open('/tmp/ifc-import-agent/default.bimcraft'))
d = json.load(open(sys.argv[1]))
want = sys.argv[2:]
names = {}
for k, v in d['library'].items():
    names[v['guid']] = '%s:%s(%s)' % (v['kind'], v['name'], k)
for k, v in d['elements'].items():
    names.setdefault(v['guid'], '#' + k)


def sub(s):
    return re.sub(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', lambda m: names.get(m.group(0), 'G?'), s)


for name, f in d['families'].items():
    if want and name not in want:
        continue
    f0 = d0['families'].get(name)
    if f0 == f and not want:
        continue
    print('==', name, 'NEW' if f0 is None else ('CHANGED' if f0 != f else 'same'))
    g = dict(f)
    forms = g.pop('forms', [])
    syms = g.pop('symbols', None)
    print('  ', sub(json.dumps(g))[:1500])
    for fm in forms:
        h = dict(fm)
        mesh = h.pop('mesh', None)
        print('   form', sub(json.dumps(h))[:400], 'mesh tris:', None if mesh is None else len(mesh))
        if mesh:
            for t in mesh[:4]:
                print('      ', t)
    if syms is not None:
        print('   symbols', sub(json.dumps(syms))[:600])

