"""A tiny IFC writer for probing: entities by id, placements, profiles, solids."""
import random
import uuid

A = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_$"


def gid(u=None):
    n = (u or uuid.uuid4()).int
    s = ''
    for i in range(22):
        s = A[n % 64] + s
        n //= 64
    return s


def fmt(x):
    if isinstance(x, bool):
        return '.T.' if x else '.F.'
    if isinstance(x, float):
        r = repr(x)
        if 'e' in r or 'E' in r:
            m, e = r.lower().split('e')
            if '.' not in m:
                m += '.'
            return m.upper() + 'E' + str(int(e))
        if r.endswith('.0'):
            return r[:-1]
        return r
    if isinstance(x, int):
        return str(x)
    if x is None:
        return '$'
    if isinstance(x, (list, tuple)):
        return '(' + ','.join(fmt(v) for v in x) + ')'
    if isinstance(x, Raw):
        return x.s
    if isinstance(x, Ref):
        return '#%d' % x.id
    if isinstance(x, str):
        return "'" + x.replace("'", "''") + "'"
    raise TypeError(x)


class Raw:
    def __init__(self, s):
        self.s = s


class Ref:
    def __init__(self, i):
        self.id = i


def E(s):
    return Raw('.' + s + '.')


class F:
    def __init__(self, schema='IFC4', units='mm'):
        self.schema = schema
        self.lines = []
        self.n = 0
        self.units = units
        self.contained = {}
        self.types = {}

    def add(self, name, *args):
        self.n += 1
        self.lines.append('#%d=%s(%s);' % (self.n, name, ','.join(fmt(a) for a in args)))
        return Ref(self.n)

    def raw(self, text):
        self.n += 1
        self.lines.append('#%d=%s;' % (self.n, text))
        return Ref(self.n)

    def pt(self, *c):
        return self.add('IFCCARTESIANPOINT', tuple(float(v) for v in c))

    def dir(self, *c):
        return self.add('IFCDIRECTION', tuple(float(v) for v in c))

    def ax3(self, o=(0, 0, 0), z=None, x=None):
        return self.add('IFCAXIS2PLACEMENT3D', self.pt(*o), self.dir(*z) if z else None, self.dir(*x) if x else None)

    def ax2(self, o=(0, 0), x=None):
        return self.add('IFCAXIS2PLACEMENT2D', self.pt(*o), self.dir(*x) if x else None)

    def lp(self, rel=None, o=(0, 0, 0), z=None, x=None):
        return self.add('IFCLOCALPLACEMENT', rel, self.ax3(o, z, x))

    def header(self, name='Project'):
        self.ctx = self.add('IFCGEOMETRICREPRESENTATIONCONTEXT', None, 'Model', 3, 1.0e-5, self.ax3(), None)
        self.body = self.add('IFCGEOMETRICREPRESENTATIONSUBCONTEXT', 'Body', 'Model', Raw('*'), Raw('*'), Raw('*'), Raw('*'), self.ctx, None, E('MODEL_VIEW'), None)
        self.axis = self.add('IFCGEOMETRICREPRESENTATIONSUBCONTEXT', 'Axis', 'Model', Raw('*'), Raw('*'), Raw('*'), Raw('*'), self.ctx, None, E('GRAPH_VIEW'), None)
        if self.units == 'mm':
            lu = self.add('IFCSIUNIT', Raw('*'), E('LENGTHUNIT'), E('MILLI'), E('METRE'))
        elif self.units == 'm':
            lu = self.add('IFCSIUNIT', Raw('*'), E('LENGTHUNIT'), None, E('METRE'))
        elif self.units == 'ft':
            m = self.add('IFCSIUNIT', Raw('*'), E('LENGTHUNIT'), None, E('METRE'))
            de = self.add('IFCDIMENSIONALEXPONENTS', 1, 0, 0, 0, 0, 0, 0)
            mwu = self.add('IFCMEASUREWITHUNIT', Raw('IFCLENGTHMEASURE(0.3048)'), m)
            lu = self.add('IFCCONVERSIONBASEDUNIT', de, E('LENGTHUNIT'), 'FOOT', mwu)
        else:
            lu = None
        us = [u for u in [lu, self.add('IFCSIUNIT', Raw('*'), E('PLANEANGLEUNIT'), None, E('RADIAN'))] if u]
        ua = self.add('IFCUNITASSIGNMENT', tuple(us))
        self.project = self.add('IFCPROJECT', gid(), None, name, None, None, None, None, (self.ctx,), ua)
        self.site_lp = self.lp()
        self.site = self.add('IFCSITE', gid(), None, 'Site', None, None, self.site_lp, None, None, E('ELEMENT'), None, None, None, None, None)
        self.bld_lp = self.lp(self.site_lp)
        self.bld = self.add('IFCBUILDING', gid(), None, 'Building', None, None, self.bld_lp, None, None, E('ELEMENT'), None, None, None)
        self.add('IFCRELAGGREGATES', gid(), None, None, None, self.project, (self.site,))
        self.add('IFCRELAGGREGATES', gid(), None, None, None, self.site, (self.bld,))
        self.storeys = []

    def storey(self, name, elev, z=None):
        lp = self.lp(self.bld_lp, (0, 0, elev if z is None else z))
        s = self.add('IFCBUILDINGSTOREY', gid(), None, name, None, None, lp, None, None, E('ELEMENT'), float(elev))
        self.storeys.append(s)
        s.lp = lp
        return s

    def close_storeys(self):
        self.add('IFCRELAGGREGATES', gid(), None, None, None, self.bld, tuple(self.storeys))

    def contain(self, storey, el):
        self.contained.setdefault(storey.id, (storey, []))[1].append(el)

    def poly2(self, pts, close=True):
        ps = [self.pt(*p) for p in pts]
        if close:
            ps.append(ps[0])
        return self.add('IFCPOLYLINE', tuple(ps))

    def poly3(self, pts, close=False):
        ps = [self.pt(*p) for p in pts]
        if close:
            ps.append(ps[0])
        return self.add('IFCPOLYLINE', tuple(ps))

    def rect(self, x, y, o=(0, 0), xdir=None):
        return self.add('IFCRECTANGLEPROFILEDEF', E('AREA'), None, self.ax2(o, xdir), float(x), float(y))

    def arb(self, pts, voids=None):
        if voids:
            return self.add('IFCARBITRARYPROFILEDEFWITHVOIDS', E('AREA'), None, self.poly2(pts), tuple(self.poly2(v) for v in voids))
        return self.add('IFCARBITRARYCLOSEDPROFILEDEF', E('AREA'), None, self.poly2(pts))

    def extrude(self, prof, depth, pos=None, d=(0, 0, 1)):
        return self.add('IFCEXTRUDEDAREASOLID', prof, pos or self.ax3(), self.dir(*d), float(depth))

    def shape(self, items, kind='SweptSolid', ident='Body', ctx=None):
        return self.add('IFCSHAPEREPRESENTATION', ctx or (self.body if ident == 'Body' else self.axis), ident, kind, tuple(items))

    def pds(self, *reps):
        return self.add('IFCPRODUCTDEFINITIONSHAPE', None, None, tuple(reps))

    def brep_box(self, x0, y0, z0, x1, y1, z1):
        P = [(x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0), (x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1)]
        faces = [(0, 3, 2, 1), (4, 5, 6, 7), (0, 1, 5, 4), (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7)]
        return self.brep(P, faces)

    def brep(self, P, faces):
        pts = [self.pt(*p) for p in P]
        fs = []
        for f in faces:
            loop = self.add('IFCPOLYLOOP', tuple(pts[i] for i in f))
            b = self.add('IFCFACEOUTERBOUND', loop, True)
            fs.append(self.add('IFCFACE', (b,)))
        sh = self.add('IFCCLOSEDSHELL', tuple(fs))
        return self.add('IFCFACETEDBREP', sh)

    def mesh(self, P, tris):
        pl = self.add('IFCCARTESIANPOINTLIST3D', tuple(tuple(float(c) for c in p) for p in P))
        return self.add('IFCTRIANGULATEDFACESET', pl, None, True, tuple(tuple(i + 1 for i in t) for t in tris), None)

    def mesh_box(self, x0, y0, z0, x1, y1, z1):
        P = [(x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0), (x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1)]
        quads = [(0, 3, 2, 1), (4, 5, 6, 7), (0, 1, 5, 4), (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7)]
        tris = []
        for q in quads:
            tris.append((q[0], q[1], q[2]))
            tris.append((q[0], q[2], q[3]))
        return self.mesh(P, tris)

    def rel_type(self, typ, els):
        self.add('IFCRELDEFINESBYTYPE', gid(), None, None, None, tuple(els), typ)

    def pset(self, els, name, props):
        ps = []
        for k, v in props.items():
            ps.append(self.add('IFCPROPERTYSINGLEVALUE', k, None, Raw(v) if isinstance(v, str) else v, None))
        s = self.add('IFCPROPERTYSET', gid(), None, name, None, tuple(ps))
        self.add('IFCRELDEFINESBYPROPERTIES', gid(), None, None, None, tuple(els), s)
        return s

    def text(self):
        for sid, (s, els) in self.contained.items():
            self.add('IFCRELCONTAINEDINSPATIALSTRUCTURE', gid(), None, None, None, tuple(els), s)
        self.contained = {}
        h = "ISO-10303-21;\nHEADER;\nFILE_DESCRIPTION(('ViewDefinition [CoordinationView]'),'2;1');\n"
        h += "FILE_NAME('x.ifc','2024-01-01T00:00:00',(''),(''),'probe','probe','');\n"
        h += "FILE_SCHEMA(('%s'));\nENDSEC;\nDATA;\n" % self.schema
        return h + '\n'.join(self.lines) + '\nENDSEC;\nEND-ISO-10303-21;\n'

    def save(self, path):
        with open(path, 'w', encoding='utf-8', newline='') as f:
            f.write(self.text())
        return path


def wall_rect(f, storey, x0, y0, x1, y1, t, h, name='W', cls='IFCWALL', axis=True, body='extrude', base=0.0, extra=None):
    """A straight wall from (x0,y0) to (x1,y1), thickness t, height h; placed at its start along its direction."""
    import math
    dx, dy = x1 - x0, y1 - y0
    L = math.hypot(dx, dy)
    ux, uy = dx / L, dy / L
    lp = f.lp(storey.lp, (x0, y0, base), (0, 0, 1), (ux, uy, 0))
    reps = []
    if body == 'extrude':
        prof = f.rect(L, t, (L / 2, 0))
        reps.append(f.shape([f.extrude(prof, h)]))
    elif body == 'brep':
        reps.append(f.shape([f.brep_box(0, -t / 2, 0, L, t / 2, h)], 'Brep'))
    elif body == 'mesh':
        reps.append(f.shape([f.mesh_box(0, -t / 2, 0, L, t / 2, h)], 'Tessellation'))
    if axis:
        reps.append(f.shape([f.poly2([(0, 0), (L, 0)], close=False)], 'Curve2D', 'Axis'))
    args = [gid(), None, name, None, None, lp, f.pds(*reps), None]
    if f.schema == 'IFC4':
        args.append(E('STANDARD') if cls != 'IFCWALLSTANDARDCASE' else E('STANDARD'))
    w = f.add(cls, *args)
    f.contain(storey, w)
    return w

