523	/// A closed loop of a curve, in plan (its z dropped), without the repeated last point.
524	pub fn loop2(m: &Model, id: u64) -> Option<Vec<V2>> {
525	    let pts = curve(m, id)?;
526	    let mut v: Vec<V2> = pts.iter().map(|p| [p[0], p[1]]).collect();
527	    while v.len() > 1 {
528	        let (a, b) = (v[0], v[v.len() - 1]);
529	        if (a[0] - b[0]).abs() < 1e-9 && (a[1] - b[1]).abs() < 1e-9 {
530	            v.pop();
531	        } else {
532	            break;
533	        }
534	    }
535	    if v.len() < 3 {
536	        return None;
537	    }
538	    Some(v)
539	}
