543	/// A profile: its outer loop and holes in its own plan, and its parametric kind.
544	pub fn profile(m: &Model, id: u64) -> Option<(Vec<V2>, Vec<Vec<V2>>, Param)> {
545	    let e = m.get(id)?;
546	    let pos = |i: usize| -> Tf { e.p(i).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID) };
547	    let tr = |tf: &Tf, v: Vec<V2>| -> Vec<V2> {
548	        v.into_iter()
549	            .map(|p| {
550	                let q = tf.apply([p[0], p[1], 0.0]);
551	                [q[0], q[1]]
552	            })
553	            .collect()
554	    };
555	    let s = m.scale;
556	    match e.name.as_str() {
557	        "IFCRECTANGLEPROFILEDEF" | "IFCROUNDEDRECTANGLEPROFILEDEF" | "IFCRECTANGLEHOLLOWPROFILEDEF" => {
558	            let tf = pos(2);
559	            let x = e.p(3).num()? * s;
560	            let y = e.p(4).num()? * s;
561	            let (hx, hy) = (x / 2.0, y / 2.0);
562	            let outer = tr(&tf, vec![[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]]);
563	            let mut holes = Vec::new();
564	            if e.name == "IFCRECTANGLEHOLLOWPROFILEDEF" {
565	                if let Some(t) = e.p(5).num() {
566	                    let t = t * s;
567	                    let (ix, iy) = (hx - t, hy - t);
568	                    if ix > 0.0 && iy > 0.0 {
569	                        holes.push(tr(&tf, vec![[-ix, -iy], [-ix, iy], [ix, iy], [ix, -iy]]));
570	                    }
571	                }
572	            }
573	            let param = Param::Rect { x, y, centre: [tf.t[0], tf.t[1]], xdir: [tf.x[0], tf.x[1]] };
574	            Some((outer, holes, param))
575	        }
576	        "IFCCIRCLEPROFILEDEF" | "IFCCIRCLEHOLLOWPROFILEDEF" => {
577	            let tf = pos(2);
578	            let r = e.p(3).num()? * s;
579	            let mut pts = arc_points([0.0, 0.0], r, 0.0, 2.0 * std::f64::consts::PI);
580	            pts.pop();
581	            let outer = tr(&tf, pts);
582	            let mut holes = Vec::new();
583	            let mut param = Param::Circle { r, centre: [tf.t[0], tf.t[1]] };
584	            if e.name == "IFCCIRCLEHOLLOWPROFILEDEF" {
585	                if let Some(t) = e.p(4).num() {
586	                    let t = t * s;
587	                    if r - t > 0.0 {
588	                        let mut ip = arc_points([0.0, 0.0], r - t, 0.0, 2.0 * std::f64::consts::PI);
589	                        ip.pop();
590	                        ip.reverse();
591	                        holes.push(tr(&tf, ip));
592	                    }
593	                    param = Param::CircleHollow { r, t, centre: [tf.t[0], tf.t[1]] };
594	                }
595	            }
596	            Some((outer, holes, param))
597	        }
598	        "IFCELLIPSEPROFILEDEF" => {
599	            let tf = pos(2);
600	            let a = e.p(3).num()? * s;
601	            let b = e.p(4).num()? * s;
602	            let n = CIRCLE_SEGMENTS;
603	            let pts: Vec<V2> = (0..n)
604	                .map(|i| {
605	                    let t = 2.0 * std::f64::consts::PI * i as f64 / n as f64;
606	                    [a * t.cos(), b * t.sin()]
607	                })
608	                .collect();
609	            Some((tr(&tf, pts), Vec::new(), Param::None))
610	        }
611	        "IFCARBITRARYCLOSEDPROFILEDEF" | "IFCARBITRARYPROFILEDEFWITHVOIDS" => {
612	            let outer = loop2(m, e.p(2).r()?)?;
613	            let mut holes = Vec::new();
614	            if e.name == "IFCARBITRARYPROFILEDEFWITHVOIDS" {
615	                for h in e.p(3).refs() {
616	                    if let Some(l) = loop2(m, h) {
617	                        holes.push(l);
618	                    }
619	                }
620	            }
621	            Some((outer, holes, Param::None))
622	        }
623	        "IFCISHAPEPROFILEDEF" | "IFCLSHAPEPROFILEDEF" | "IFCTSHAPEPROFILEDEF" | "IFCUSHAPEPROFILEDEF" | "IFCCSHAPEPROFILEDEF"
624	        | "IFCZSHAPEPROFILEDEF" | "IFCASYMMETRICISHAPEPROFILEDEF" => {
625	            // the section's bounding rectangle: its overall width and depth
626	            let tf = pos(2);
627	            let (w, d) = match e.name.as_str() {
628	                "IFCISHAPEPROFILEDEF" | "IFCASYMMETRICISHAPEPROFILEDEF" => (e.p(3).num()? * s, e.p(4).num()? * s),
629	                "IFCLSHAPEPROFILEDEF" => (e.p(4).num().unwrap_or(e.p(3).num()?) * s, e.p(3).num()? * s),
630	                "IFCTSHAPEPROFILEDEF" => (e.p(4).num()? * s, e.p(3).num()? * s),
631	                "IFCUSHAPEPROFILEDEF" => (e.p(4).num()? * s, e.p(3).num()? * s),
632	                "IFCCSHAPEPROFILEDEF" => (e.p(4).num()? * s, e.p(3).num()? * s),
633	                _ => (e.p(4).num()? * s, e.p(3).num()? * s),
634	            };
635	            let (hx, hy) = (w / 2.0, d / 2.0);
636	            let outer = tr(&tf, vec![[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]]);
637	            Some((outer, Vec::new(), Param::Rect { x: w, y: d, centre: [tf.t[0], tf.t[1]], xdir: [tf.x[0], tf.x[1]] }))
638	        }
639	        "IFCDERIVEDPROFILEDEF" => {
640	            let (o, h, _) = profile(m, e.p(2).r()?)?;
641	            let op = e.p(3).r().map(|r| operator(m, r)).unwrap_or(Tf::ID);
642	            Some((tr(&op, o), h.into_iter().map(|l| tr(&op, l)).collect(), Param::None))
643	        }
644	        _ => None,
645	    }
646	}
