661	fn extrusion(m: &Model, e: &Entity, tf: &Tf, item: u64) -> Option<Solid> {
662	    // IfcExtrudedAreaSolid(SweptArea, Position, ExtrudedDirection, Depth)
663	    let (outer, holes, param) = profile(m, e.p(0).r()?)?;
664	    let pos = e.p(1).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID);
665	    let d = unit(dir3(m, e.p(2)).unwrap_or([0.0, 0.0, 1.0]));
666	    let depth = e.p(3).num()? * m.scale;
667	    let ptf = tf.then(&pos);
668	    let ext = Extrusion { outer, holes, tf: ptf, dir: d, depth, param };
669	    let faces = extrusion_faces(&ext);
670	    Some(Solid { faces, ext: Some(ext), item, clipped: false, clips: Vec::new() })
671	}
