673	/// The faces of an extrusion: its base, its top and its sides.
674	pub fn extrusion_faces(x: &Extrusion) -> Vec<Face> {
675	    let off = mul(x.dir, x.depth);
676	    let at = |p: &V2, top: bool| -> V3 {
677	        let q = [p[0], p[1], 0.0];
678	        x.tf.apply(if top { add(q, off) } else { q })
679	    };
680	    let mut faces = Vec::new();
681	    let ccw = area2(&x.outer) >= 0.0;
682	    let ring = |l: &Vec<V2>, top: bool, rev: bool| -> Vec<V3> {
683	        let mut v: Vec<V3> = l.iter().map(|p| at(p, top)).collect();
684	        if rev {
685	            v.reverse();
686	        }
687	        v
688	    };
689	    faces.push(Face { outer: ring(&x.outer, false, ccw), holes: x.holes.iter().map(|h| ring(h, false, !ccw)).collect() });
690	    faces.push(Face { outer: ring(&x.outer, true, !ccw), holes: x.holes.iter().map(|h| ring(h, true, ccw)).collect() });
691	    let mut side = |l: &Vec<V2>| {
692	        let n = l.len();
693	        for i in 0..n {
694	            let (a, b) = (&l[i], &l[(i + 1) % n]);
695	            faces.push(Face { outer: vec![at(a, false), at(b, false), at(b, true), at(a, true)], holes: Vec::new() });
696	        }
697	    };
698	    side(&x.outer);
699	    for h in &x.holes {
700	        side(h);
701	    }
702	    faces
703	}
