705	fn loop_points(m: &Model, id: u64, tf: &Tf) -> Option<Vec<V3>> {
706	    let e = m.get(id)?;
707	    match e.name.as_str() {
708	        "IFCPOLYLOOP" => {
709	            let mut v = Vec::new();
710	            for r in e.p(0).refs() {
711	                v.push(tf.apply(p3(m, r)?));
712	            }
713	            Some(v)
714	        }
715	        _ => {
716	            let pts = curve(m, id)?;
717	            Some(pts.into_iter().map(|p| tf.apply(p)).collect())
718	        }
