722	fn face_of(m: &Model, id: u64, tf: &Tf) -> Option<Face> {
723	    let e = m.get(id)?;
724	    // IfcFace(Bounds) / IfcFaceSurface(Bounds, FaceSurface, SameSense)
725	    let mut outer: Option<Vec<V3>> = None;
726	    let mut holes = Vec::new();
727	    for b in e.p(0).refs() {
728	        let be = m.get(b)?;
729	        let mut pts = loop_points(m, be.p(0).r()?, tf)?;
730	        if be.p(1).boolean() == Some(false) {
731	            pts.reverse();
732	        }
733	        if be.name == "IFCFACEOUTERBOUND" && outer.is_none() {
734	            outer = Some(pts);
735	        } else {
736	            holes.push(pts);
737	        }
738	    }
739	    let outer = match outer {
740	        Some(o) => o,
741	        None => {
742	            if holes.is_empty() {
743	                return None;
744	            }
745	            holes.remove(0)
746	        }
747	    };
748	    Some(Face { outer, holes })
749	}
