784	/// The solids of a representation item, in the project's coordinates.
785	pub fn item_solids(m: &Model, id: u64, tf: &Tf, out: &mut Vec<Solid>, depth: usize) {
786	    if depth > 32 {
787	        return;
788	    }
789	    let e = match m.get(id) {
790	        Some(e) => e,
791	        None => return,
792	    };
793	    match e.name.as_str() {
794	        "IFCEXTRUDEDAREASOLID" | "IFCEXTRUDEDAREASOLIDTAPERED" => {
795	            if let Some(s) = extrusion(m, e, tf, id) {
796	                out.push(s);
797	            }
798	        }
799	        "IFCFACETEDBREP" | "IFCFACETEDBREPWITHVOIDS" | "IFCADVANCEDBREP" | "IFCADVANCEDBREPWITHVOIDS" => {
800	            let mut faces = Vec::new();
801	            if let Some(sh) = e.p(0).r() {
802	                shell_faces(m, sh, tf, &mut faces);
803	            }
804	            if !faces.is_empty() {
805	                out.push(Solid { faces, ext: None, item: id, clipped: false, clips: Vec::new() });
806	            }
807	        }
808	        "IFCSHELLBASEDSURFACEMODEL" | "IFCFACEBASEDSURFACEMODEL" => {
809	            let mut faces = Vec::new();
810	            for sh in e.p(0).refs() {
811	                shell_faces(m, sh, tf, &mut faces);
812	            }
813	            if !faces.is_empty() {
814	                out.push(Solid { faces, ext: None, item: id, clipped: false, clips: Vec::new() });
815	            }
816	        }
817	        "IFCCLOSEDSHELL" | "IFCOPENSHELL" | "IFCCONNECTEDFACESET" => {
818	            let mut faces = Vec::new();
819	            shell_faces(m, id, tf, &mut faces);
820	            if !faces.is_empty() {
821	                out.push(Solid { faces, ext: None, item: id, clipped: false, clips: Vec::new() });
822	            }
823	        }
824	        "IFCTRIANGULATEDFACESET" | "IFCTRIANGULATEDIRREGULARNETWORK" => {
825	            // (Coordinates, Normals, Closed, CoordIndex, PnIndex)
826	            let pts = match e.p(0).r().and_then(|r| point_list(m, r, tf)) {
827	                Some(p) => p,
828	                None => return,
829	            };
830	            let pn: Vec<i64> = e.p(4).list().map(|l| l.iter().filter_map(|x| x.int()).collect()).unwrap_or_default();
831	            let at = |i: i64| -> Option<V3> {
832	                let j = if pn.is_empty() { i } else { *pn.get((i - 1) as usize)? };
833	                pts.get((j - 1) as usize).copied()
834	            };
835	            let mut faces = Vec::new();
836	            for t in index_list(e.p(3)) {
837	                let v: Option<Vec<V3>> = t.iter().map(|i| at(*i)).collect();
838	                if let Some(v) = v {
839	                    if v.len() >= 3 {
840	                        faces.push(Face { outer: v, holes: Vec::new() });
841	                    }
842	                }
843	            }
844	            if !faces.is_empty() {
845	                out.push(Solid { faces, ext: None, item: id, clipped: false, clips: Vec::new() });
846	            }
847	        }
848	        "IFCPOLYGONALFACESET" => {
849	            // (Coordinates, Closed, Faces, PnIndex)
850	            let pts = match e.p(0).r().and_then(|r| point_list(m, r, tf)) {
851	                Some(p) => p,
852	                None => return,
853	            };
854	            let pn: Vec<i64> = e.p(3).list().map(|l| l.iter().filter_map(|x| x.int()).collect()).unwrap_or_default();
855	            let at = |i: i64| -> Option<V3> {
856	                let j = if pn.is_empty() { i } else { *pn.get((i - 1) as usize)? };
857	                pts.get((j - 1) as usize).copied()
858	            };
859	            let mut faces = Vec::new();
860	            for f in e.p(2).refs() {
861	                let fe = match m.get(f) {
862	                    Some(x) => x,
863	                    None => continue,
864	                };
865	                let idx: Vec<i64> = fe.p(0).list().map(|l| l.iter().filter_map(|x| x.int()).collect()).unwrap_or_default();
866	                let outer: Option<Vec<V3>> = idx.iter().map(|i| at(*i)).collect();
867	                let mut holes = Vec::new();
868	                if fe.name == "IFCINDEXEDPOLYGONALFACEWITHVOIDS" {
869	                    for h in index_list(fe.p(1)) {
870	                        if let Some(hv) = h.iter().map(|i| at(*i)).collect::<Option<Vec<V3>>>() {
871	                            holes.push(hv);
872	                        }
873	                    }
874	                }
875	                if let Some(o) = outer {
876	                    if o.len() >= 3 {
877	                        faces.push(Face { outer: o, holes });
878	                    }
879	                }
880	            }
881	            if !faces.is_empty() {
882	                out.push(Solid { faces, ext: None, item: id, clipped: false, clips: Vec::new() });
883	            }
884	        }
885	        "IFCBOOLEANCLIPPINGRESULT" | "IFCBOOLEANRESULT" => {
886	            // (Operator, FirstOperand, SecondOperand): the first operand, its clips noted
887	            let first = match e.p(1).r() {
888	                Some(r) => r,
889	                None => return,
890	            };
891	            let mut inner = Vec::new();
892	            item_solids(m, first, tf, &mut inner, depth + 1);
893	            let op = e.p(0).enm().unwrap_or("");
894	            let mut clips = Vec::new();
895	            if op == "DIFFERENCE" {
896	                if let Some(sec) = e.p(2).r() {
897	                    if let Some(h) = half_space(m, sec, tf) {
898	                        clips.push(h);
899	                    }
900	                }
901	            }
902	            for mut s in inner {
903	                s.clipped = true;
904	                s.clips.extend(clips.iter().copied());
905	                out.push(s);
906	            }
907	        }
908	        "IFCMAPPEDITEM" => {
909	            // (MappingSource: IfcRepresentationMap(MappingOrigin, MappedRepresentation), MappingTarget)
910	            let src = match e.p(0).r().and_then(|r| m.get(r)) {
911	                Some(s) => s,
912	                None => return,
913	            };
914	            let origin = src.p(0).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID);
915	            let target = e.p(1).r().map(|r| operator(m, r)).unwrap_or(Tf::ID);
916	            let t2 = tf.then(&target).then(&origin);
917	            if let Some(rep) = src.p(1).r().and_then(|r| m.get(r)) {
918	                for it in rep.p(3).refs() {
919	                    item_solids(m, it, &t2, out, depth + 1);
920	                }
921	            }
922	        }
923	        _ => {}
924	    }
925	}
