927	/// A half space solid as a plane (a point, and the normal out of what is kept).
928	fn half_space(m: &Model, id: u64, tf: &Tf) -> Option<(V3, V3)> {
929	    let e = m.get(id)?;
930	    match e.name.as_str() {
931	        "IFCHALFSPACESOLID" | "IFCPOLYGONALBOUNDEDHALFSPACE" | "IFCBOXEDHALFSPACE" => {
932	            // (BaseSurface: IfcPlane(Position), AgreementFlag, …)
933	            let pl = m.get(e.p(0).r()?)?;
934	            if pl.name != "IFCPLANE" {
935	                return None;
936	            }
937	            let ptf = tf.then(&pl.p(0).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID));
938	            let n = unit(ptf.z);
939	            // AgreementFlag true: the half space is on the side the normal points to; it is
940	            // taken away, so what is kept lies behind the plane
941	            let agree = e.p(1).boolean().unwrap_or(true);
942	            Some((ptf.t, if agree { n } else { mul(n, -1.0) }))
943	        }
944	        _ => None,
945	    }
946	}
