648	/// The signed area of a plan loop (counter-clockwise positive).
649	pub fn area2(v: &[V2]) -> f64 {
650	    let n = v.len();
651	    let mut a = 0.0;
652	    for i in 0..n {
653	        let (p, q) = (v[i], v[(i + 1) % n]);
654	        a += p[0] * q[1] - q[0] * p[1];
655	    }
656	    a / 2.0
657	}
