8	/// The outline of a body in plan: an extrusion's profile (where it is extruded up), else the
9	/// biggest face that looks down.
10	pub fn footprint(solids: &[Solid]) -> Option<Vec<V2>> {
11	    for s in solids {
12	        if let Some(x) = &s.ext {
13	            let d = x.tf.dir(x.dir);
14	            if d[2].abs() > 0.999 {
15	                let v: Vec<V2> = x
16	                    .outer
17	                    .iter()
18	                    .map(|p| {
19	                        let q = x.tf.apply([p[0], p[1], 0.0]);
20	                        [q[0], q[1]]
21	                    })
22	                    .collect();
23	                return Some(v);
24	            }
25	        }
26	    }
27	    let mut best: Option<(f64, Vec<V2>)> = None;
28	    for s in solids {
29	        for f in &s.faces {
30	            let n = super::import_walls::face_normal(&f.outer);
31	            if n[2] < -0.999 {
32	                let v: Vec<V2> = f.outer.iter().map(|p| [p[0], p[1]]).collect();
33	                let a = geom::area2(&v).abs();
34	                if best.as_ref().map(|(b, _)| a > *b).unwrap_or(true) {
35	                    best = Some((a, v));
36	                }
37	            }
38	        }
39	    }
40	    best.map(|(_, v)| v)
41	}
