43	fn cross(o: V2, a: V2, b: V2) -> f64 {
44	    (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
45	}
46	
47	/// A point inside a polygon: the centre of the biggest triangle ear clipping cuts it into (the
48	/// polygon counter-clockwise from its lowest point, each ear the first from there; the last
49	/// of equal ones).
50	pub fn inside_point(poly: &[V2]) -> Option<V2> {
51	    let mut v: Vec<V2> = super::import_slabs::simplify(poly);
52	    if v.len() < 3 {
53	        return None;
54	    }
55	    if geom::area2(&v) < 0.0 {
56	        v.reverse();
57	    }
58	    let mut k = 0;
59	    for i in 1..v.len() {
60	        if v[i][1] < v[k][1] || (v[i][1] == v[k][1] && v[i][0] < v[k][0]) {
61	            k = i;
62	        }
63	    }
64	    v.rotate_left(k);
65	    let mut tris: Vec<[V2; 3]> = Vec::new();
66	    let mut guard = 0;
67	    while v.len() > 3 && guard < 100000 {
68	        guard += 1;
69	        let n = v.len();
70	        let mut clipped = false;
71	        for j in 0..n {
72	            let (a, b, c) = (v[(j + n - 1) % n], v[j], v[(j + 1) % n]);
73	            if cross(a, b, c) <= 0.0 {
74	                continue;
75	            }
76	            let mut ok = true;
77	            for q in &v {
78	                if *q == a || *q == b || *q == c {
79	                    continue;
80	                }
81	                if cross(a, b, *q) >= 0.0 && cross(b, c, *q) >= 0.0 && cross(c, a, *q) >= 0.0 {
82	                    ok = false;
83	                    break;
84	                }
85	            }
86	            if ok {
87	                tris.push([a, b, c]);
88	                v.remove(j);
89	                clipped = true;
90	                break;
91	            }
92	        }
93	        if !clipped {
94	            break;
95	        }
96	    }
97	    if v.len() == 3 {
98	        tris.push([v[0], v[1], v[2]]);
99	    }
100	    let mut best: Option<([V2; 3], f64)> = None;
101	    for t in tris {
102	        let a = ((t[1][0] - t[0][0]) * (t[2][1] - t[0][1]) - (t[1][1] - t[0][1]) * (t[2][0] - t[0][0])).abs() / 2.0;
103	        if best.map(|(_, b)| a >= b).unwrap_or(true) {
104	            best = Some((t, a));
105	        }
106	    }
107	    let (t, _) = best?;
108	    Some([(t[0][0] + t[1][0] + t[2][0]) / 3.0, (t[0][1] + t[1][1] + t[2][1]) / 3.0])
109	}
