111	pub fn rooms(ctx: &mut Ctx) {
112	    let ids: Vec<u64> = ctx.m.of("IFCSPACE").to_vec();
113	    let mut n = 0;
114	    for id in ids {
115	        n += 1;
116	        room(ctx, id, n);
