120	fn room(ctx: &mut Ctx, id: u64, n: usize) {
121	    let e = ctx.m.get(id).unwrap().clone();
122	    let solids = geom::body(&ctx.m, id);
123	    let point = footprint(&solids).and_then(|f| inside_point(&f)).unwrap_or([0.0, 0.0]);
124	    let z = solids.iter().flat_map(|s| s.points().map(|p| p[2]).collect::<Vec<_>>()).fold(f64::INFINITY, f64::min);
125	    let level = ctx.level_of(id, if z.is_finite() { z } else { 0.0 });
126	    let name = e
127	        .p(7)
128	        .str()
129	        .map(|s| s.trim().to_string())
130	        .filter(|s| !s.is_empty())
131	        .or_else(|| e.p(2).str().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()))
132	        .unwrap_or_else(|| "Room".to_string());
133	    let colour = solids.iter().find_map(|s| ctx.m.styled.get(&s.item).and_then(|si| super::import_types::styled_item_colour(ctx, *si))).and_then(|c| c.0);
134	    let g = ctx.guid_for(id);
135	    let mut v = crate::jobj! {
136	        "guid" => g.as_str(),
137	        "category" => "room",
138	        "level" => ctx.level_guid(level),
139	        "point" => Value::Arr(vec![Value::f(r3(point[0])), Value::f(r3(point[1]))]),
140	        "name" => name,
141	        "number" => n.to_string(),
142	    };
143	    if let Some(c) = colour {
144	        v.set("colour", Value::Arr(c.iter().map(|x| Value::u(*x)).collect()));
145	    }
146	    ctx.add(id, v);
147	}
