10	/// The colour (0–255) and transparency (0–100) a material's style gives it.
11	pub fn material_style(ctx: &Ctx, mat: u64) -> (Option<[u64; 3]>, Option<f64>) {
12	    let m = &ctx.m;
13	    for id in m.of("IFCMATERIALDEFINITIONREPRESENTATION") {
14	        let e = match m.get(*id) {
15	            Some(e) => e,
16	            None => continue,
17	        };
18	        if e.p(3).r() != Some(mat) {
19	            continue;
20	        }
21	        for sr in e.p(2).refs() {
22	            let sre = match m.get(sr) {
23	                Some(x) => x,
24	                None => continue,
25	            };
26	            for si in sre.p(3).refs() {
27	                if let Some(c) = styled_item_colour(ctx, si) {
28	                    return c;
29	                }
30	            }
31	        }
32	    }
33	    (None, None)
34	}
35	
36	/// The surface colour of a styled item (or a surface style): its shading's colour.
37	pub fn styled_item_colour(ctx: &Ctx, si: u64) -> Option<(Option<[u64; 3]>, Option<f64>)> {
38	    let m = &ctx.m;
39	    let e = m.get(si)?;
40	    let styles: Vec<u64> = match e.name.as_str() {
41	        "IFCSTYLEDITEM" => {
42	            let mut v = Vec::new();
43	            for s in e.p(1).refs() {
44	                // IFC2x3: IfcPresentationStyleAssignment(Styles)
45	                match m.get(s).map(|x| x.name.as_str()) {
46	                    Some("IFCPRESENTATIONSTYLEASSIGNMENT") => v.extend(m.get(s).unwrap().p(0).refs()),
47	                    _ => v.push(s),
48	                }
49	            }
50	            v
51	        }
52	        "IFCSURFACESTYLE" => vec![si],
53	        _ => return None,
54	    };
55	    for s in styles {
56	        let se = match m.get(s) {
57	            Some(x) => x,
58	            None => continue,
59	        };
60	        if se.name != "IFCSURFACESTYLE" {
61	            continue;
62	        }
63	        for el in se.p(2).refs() {
64	            let ee = match m.get(el) {
65	                Some(x) => x,
66	                None => continue,
67	            };
68	            if ee.name == "IFCSURFACESTYLESHADING" || ee.name == "IFCSURFACESTYLERENDERING" {
69	                let c = ee.p(0).r().and_then(|c| m.get(c));
70	                let rgb = c.and_then(|c| {
71	                    if c.name != "IFCCOLOURRGB" {
72	                        return None;
73	                    }
74	                    let f = |i: usize| -> Option<u64> {
75	                        let x = c.p(i).num()?;
76	                        Some((x.clamp(0.0, 1.0) * 255.0).round() as u64)
77	                    };
78	                    Some([f(1)?, f(2)?, f(3)?])
79	                });
80	                let tr = ee.p(1).num();
81	                return Some((rgb, tr));
82	            }
83	        }
84	    }
85	    None
86	}
