88	/// The library material a file's material comes in as (by its name, given its colour), and
89	/// its GUID.
90	pub fn material(ctx: &mut Ctx, mat: u64) -> Option<String> {
91	    let e = ctx.m.get(mat)?;
92	    if e.name != "IFCMATERIAL" {
93	        return None;
94	    }
95	    let name = e.p(0).str()?.trim().to_string();
96	    if name.is_empty() {
97	        return None;
98	    }
99	    let (rgb, _tr) = material_style(ctx, mat);
100	    let mats = ctx.pr.section_mut("materials");
101	    match mats.get_mut(&name) {
102	        Some(v) => {
103	            if let Some(c) = rgb {
104	                v.set("color", Value::Arr(c.iter().map(|x| Value::u(*x)).collect()));
105	            }
106	        }
107	        None => {
108	            let c = rgb.unwrap_or([200, 200, 200]);
109	            let v = crate::jobj! {
110	                "color" => Value::Arr(c.iter().map(|x| Value::u(*x)).collect()),
111	                "cut" => "none",
112	                "surface" => "none",
113	            };
114	            mats.insert_sorted(&name, v);
115	        }
116	    }
117	    Some(ctx.lib.get(&ctx.pr, "material", &name))
118	}
