120	/// A material layer set's layers as a type's: each layer's function, material and thickness.
121	pub fn layers(ctx: &mut Ctx, set: u64) -> Option<(Vec<Value>, f64)> {
122	    let e = ctx.m.get(set)?.clone();
123	    let mut out: Vec<(Option<String>, Option<String>, f64)> = Vec::new();
124	    let mut variable: Vec<bool> = Vec::new();
125	    let s = ctx.m.scale;
126	    let ifc4 = ctx.m.is_ifc4();
127	    for l in e.p(0).refs() {
128	        let le = ctx.m.get(l)?.clone();
129	        let th = le.p(1).num().unwrap_or(0.0) * s;
130	        let mat = le.p(0).r().and_then(|m| material(ctx, m));
131	        let cat = if ifc4 { le.p(5).str().map(|x| x.to_string()) } else { None };
132	        // IFC4's Description `Variable`: a layer whose thickness varies (a screed to falls)
133	        variable.push(ifc4 && le.p(4).str() == Some("Variable"));
134	        let f = if th == 0.0 {
135	            Some("membrane".to_string())
136	        } else {
137	            cat.as_deref().map(|c| {
138	                match c {
139	                    "Finish" => "finish",
140	                    "Insulation" => "thermal",
141	                    "LoadBearing" => "structure",
142	                    "Membrane" => "membrane",
143	                    _ => "substrate",
144	                }
145	                .to_string()
146	            })
147	        };
148	        out.push((f, mat, th));
149	    }
150	    if out.is_empty() {
151	        return None;
152	    }
153	    // with no layer saying what it is, the thickest carries the load
154	    if out.iter().all(|l| l.0.is_none()) {
155	        let mut best = 0;
156	        for (i, l) in out.iter().enumerate() {
157	            if l.2 > out[best].2 {
158	                best = i;
159	            }
160	        }
161	        out[best].0 = Some("structure".into());
162	    }
163	    let total: f64 = out.iter().map(|l| l.2).sum();
164	    let v = out
165	        .into_iter()
166	        .zip(variable)
167	        .map(|((f, m, t), var)| {
168	            let mut o = Map::new();
169	            o.insert("function", Value::s(f.as_deref().unwrap_or("substrate")));
170	            o.insert("material", Value::s(m.as_deref().unwrap_or("")));
171	            o.insert("thickness", Value::f(r3(t)));
172	            if var {
173	                o.insert("variable", Value::Bool(true));
174	            }
175	            Value::Obj(o)
176	        })
177	        .collect();
178	    Some((v, total))
179	}
