187	/// An element's name where it isn't its type's (the type as the file names it): its mark.
188	pub fn mark_of(ctx: &Ctx, id: u64, type_name: &str) -> Option<String> {
189	    let n = ctx.m.name(id)?.trim().to_string();
190	    if n.is_empty() || n == type_name {
