196	/// The layer set of an element: its usage's, else its type's, else its own.
197	fn layer_set(ctx: &Ctx, id: u64, usage: Option<&Usage>) -> Option<u64> {
198	    if let Some(u) = usage {
199	        return Some(u.set);
200	    }
201	    let pick = |x: u64| -> Option<u64> {
202	        let mid = *ctx.m.material_of.get(&x)?;
203	        let e = ctx.m.get(mid)?;
204	        match e.name.as_str() {
205	            "IFCMATERIALLAYERSET" => Some(mid),
206	            "IFCMATERIALLAYERSETUSAGE" => e.p(0).r(),
207	            _ => None,
208	        }
209	    };
210	    if let Some(s) = pick(id) {
211	        return Some(s);
212	    }
213	    let t = *ctx.m.type_of.get(&id)?;
214	    pick(t)
215	}
