217	/// A type registered for a category: the same one for the same name and values within the
218	/// import, else under the name (or `Name (2)`…) next to what the project has.
219	pub fn register(ctx: &mut Ctx, cat: &str, name: &str, v: Value) -> String {
220	    let key = (cat.to_string(), name.to_string(), build::strip_ids(&v).to_compact());
221	    if let Some(n) = ctx.type_names.get(&key) {
222	        return n.clone();
223	    }
224	    // a type the project has is taken only when it is the same in every part (a layer is a
225	    // part of its own: one made now is never one the project had)
226	    let m = build::types_map(&mut ctx.pr, cat);
227	    let mut k = 1;
228	    let n = loop {
229	        let cand = if k == 1 { name.to_string() } else { format!("{} ({})", name, k) };
230	        match m.get(&cand) {
231	            Some(x) => {
232	                if *x == v {
233	                    break cand;
234	                }
235	            }
236	            None => {
237	                m.insert_sorted(&cand, v);
238	                break cand;
239	            }
240	        }
241	        k += 1;
242	    };
243	    ctx.type_names.insert(key, n.clone());
244	    n
245	}
