247	/// A wall's type: the file's type name (or `Imported - 200mm`), its thickness, and its layers
248	/// where they make up that thickness.
249	pub fn wall_type(ctx: &mut Ctx, id: u64, thickness: f64, usage: Option<&Usage>) -> String {
250	    let t = r3(thickness);
251	    let name = file_type_name(ctx, id).unwrap_or_else(|| format!("Imported - {}mm", num_name(t)));
252	    let mut v = crate::jobj! {"thickness" => t};
253	    if let Some(set) = layer_set(ctx, id, usage) {
254	        if let Some((ls, total)) = layers(ctx, set) {
255	            if (r3(total) - t).abs() < 0.5 {
256	                v.set("layers", Value::Arr(ls.into_iter().map(with_part_id).collect()));
257	            }
258	        }
259	    }
260	    register(ctx, "wall", &name, v)
261	}
