263	/// A part (a layer) as the core writes one new: its id and GUID first.
264	pub fn with_part_id(v: Value) -> Value {
265	    let mut o = Map::new();
266	    o.insert("id", Value::u(0));
267	    o.insert("guid", Value::s(&crate::rand::guid()));
268	    if let Value::Obj(m) = v {
269	        for (k, x) in m.items {
270	            o.items.push((k, x));
271	        }
272	    }
273	    Value::Obj(o)
274	}
