276	/// A door's or window's type: the file's type name (or the element's name), its size and sill,
277	/// and how it opens.
278	pub fn opening_type(ctx: &mut Ctx, id: u64, cat: &str, width: f64, height: f64, sill: f64, op: Option<&str>) -> String {
279	    let name = file_type_name(ctx, id)
280	        .or_else(|| ctx.m.name(id).map(|n| n.trim().to_string()).filter(|n| !n.is_empty()))
281	        .unwrap_or_else(|| format!("{} x {}", num_name(width), num_name(height)));
282	    // the sill is each one's own: a type the project has keeps its own
283	    let sill = build::type_value(&ctx.pr, cat, &name).and_then(|t| t.get("sill")).and_then(|s| s.as_f64()).unwrap_or(sill);
284	    let mut v = crate::jobj! {"width" => width, "height" => height, "sill" => sill};
285	    if let Some(o) = op {
286	        v.set("operation", Value::s(o));
287	    }
288	    register(ctx, cat, &name, v)
289	}
290	
291	pub type TypeNames = BTreeMap<(String, String, String), String>;
