1	//! Reading IFC2x3 and IFC4 files into a project.
2	
3	use super::import_build::{self as build, LibGuids};
4	use super::import_geom as geom;
5	use super::import_model::{guid_of_global_id, Model};
6	use super::step;
7	use crate::json::{Map, Value};
8	use crate::project::Project;
9	use crate::session::Session;
10	use std::collections::{BTreeMap, BTreeSet};
11	
12	/// A level of the project as the import knows it.
13	#[derive(Clone, Debug)]
14	pub struct Lvl {
15	    /// The storey's entity, if it came from one.
16	    pub ent: Option<u64>,
17	    pub name: String,
18	    pub elevation: f64,
19	    pub guid: String,
20	}
21	
22	/// An element that came in.
23	#[derive(Clone, Debug)]
24	pub struct Made {
25	    pub id: u64,
26	    pub guid: String,
27	    pub cat: String,
28	}
29	
30	pub struct Ctx {
31	    pub m: Model,
32	    pub pr: Project,
33	    pub path: String,
34	    pub levels: Vec<Lvl>,
35	    pub skipped: Vec<String>,
36	    /// The file's entities that came in, and what they became.
37	    pub made: BTreeMap<u64, Made>,
38	    pub used_guids: BTreeSet<String>,
39	    pub lib: LibGuids,
40	    /// What later passes need of the walls: entity → its measured line.
41	    pub walls: BTreeMap<u64, super::import_walls::WallLine>,
42	    /// The types made so far: (category, name, values) → the name it has.
43	    pub type_names: super::import_types::TypeNames,
44	    /// What each kind's pass keeps for the later ones (each module owns its own).
45	    pub slabs: super::import_slabs::State,
46	    pub roofs: super::import_roofs::State,
47	    pub structure: super::import_structure::State,
48	    pub circulation: super::import_circulation::State,
49	    pub components: super::import_components::State,
50	    pub params: super::import_params::State,
51	}
52	
53	impl Ctx {
54	    /// The GUID an entity comes in with: its GlobalId's, unless it is no GUID or one already
55	    /// taken; then a new one.
56	    pub fn guid_for(&mut self, ent: u64) -> String {
57	        let g = self.m.get(ent).and_then(|e| e.p(0).str()).and_then(guid_of_global_id);
58	        let g = match g {
59	            Some(g) if !self.used_guids.contains(&g) => g,
60	            _ => crate::rand::guid(),
61	        };
62	        self.used_guids.insert(g.clone());
63	        g
64	    }
65	
66	    /// Adds an element; returns its project id.
67	    pub fn add(&mut self, ent: u64, v: Value) -> u64 {
68	        let id = self.pr.alloc_id();
69	        let g = v.get("guid").and_then(|g| g.as_str()).unwrap_or("").to_string();
70	        let cat = v.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
71	        self.pr.elements.insert(id, v);
72	        self.made.insert(ent, Made { id, guid: g, cat });
73	        id
74	    }
75	
76	    /// Says an element was left out, and why.
77	    pub fn skip(&mut self, ent: u64, why: &str) {
78	        let line = self.describe(ent);
79	        self.skipped.push(format!("{}: {}", line, why));
80	    }
81	
82	    /// `IFCWALL #39 'W'`: an element as the reply names it.
83	    pub fn describe(&self, ent: u64) -> String {
84	        let class = self.m.class(ent).to_string();
85	        match self.m.name(ent) {
86	            Some(n) => format!("{} #{} '{}'", class, ent, n),
87	            None => format!("{} #{}", class, ent),
88	        }
89	    }
90	
91	    pub fn type_guid(&mut self, cat: &str, name: &str) -> String {
92	        let kind = build::type_kind(cat);
93	        self.lib.get(&self.pr, &kind, name)
94	    }
95	
96	    pub fn level_guid(&self, i: usize) -> Value {
97	        Value::s(&self.levels[i].guid)
98	    }
99	
100	    /// The level an element stands on: its storey's, else the highest at or below `z`, else the
101	    /// lowest.
102	    pub fn level_of(&self, ent: u64, z: f64) -> usize {
103	        if let Some(s) = self.m.container(ent) {
104	            if let Some(i) = self.levels.iter().position(|l| l.ent == Some(s)) {
105	                return i;
106	            }
107	        }
108	        self.level_at(z)
109	    }
110	
111	    /// The highest level at or below `z` (within a millimetre), else the lowest.
112	    pub fn level_at(&self, z: f64) -> usize {
113	        let mut best: Option<usize> = None;
114	        for (i, l) in self.levels.iter().enumerate() {
115	            if l.elevation <= z + 1.0 {
116	                best = Some(i);
117	            }
118	        }
119	        best.unwrap_or(0)
120	    }
121	
122	    /// A level whose elevation is at `z` (within a millimetre), above level `base`.
123	    pub fn level_at_top(&self, base: usize, z: f64) -> Option<usize> {
124	        for (i, l) in self.levels.iter().enumerate() {
125	            if i != base && (l.elevation - z).abs() <= 1.0 && l.elevation > self.levels[base].elevation {
126	                return Some(i);
127	            }
128	        }
129	        None
130	    }
131	}
132	
133	fn file_stem(path: &str) -> String {
134	    std::path::Path::new(path).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()
135	}
136	
137	/// Imports an IFC file as a new project into the session (what `run x.ifc`, `convert` and
138	/// `open` do); returns the reply `run` prints. An error is what follows `open: `.
139	pub fn import(s: &mut Session, path: &str) -> Result<Value, String> {
140	    let bytes = std::fs::read(path).map_err(|e| format!("{}: {}", path, crate::commands::io_err(&e)))?;
141	    let (pr, reply) = read(&bytes, path)?;
142	    s.project = pr;
143	    s.now_phase = None;
144	    s.now_option = None;
145	    s.path = None;
146	    s.undo.clear();
147	    s.redo.clear();
148	    Ok(reply)
149	}
150	
151	/// Reads an IFC file's bytes into a project, and the reply an import makes.
152	pub fn read(bytes: &[u8], path: &str) -> Result<(Project, Value), String> {
153	    let f = step::parse(bytes).map_err(|e| format!("{}: {}", path, e))?;
154	    let schema = f.schema();
155	    if schema.is_empty() {
156	        return Err(format!("{}: this STEP file is in no schema, not IFC", path));
157	    }
158	    if !schema.starts_with("IFC") {
159	        return Err(format!("{}: this STEP file is in {}, not IFC", path, schema));
160	    }
161	    let project = f.entities.iter().find(|(_, e)| e.name == "IFCPROJECT").map(|(id, _)| *id);
162	    let project = match project {
163	        Some(p) => p,
164	        None => return Err(format!("{}: it has no IfcProject", path)),
165	    };
166	    let mut m = Model::new(f, schema.clone());
167	    m.read_units(project);
168	    let name = match m.name(project).map(|n| n.trim().to_string()) {
169	        Some(n) if !n.is_empty() => n,
170	        _ => file_stem(path),
171	    };
172	    let pr = build::new_project(&name);
173	    let mut ctx = Ctx {
174	        m,
175	        pr,
176	        path: path.to_string(),
177	        levels: Vec::new(),
178	        skipped: Vec::new(),
179	        made: BTreeMap::new(),
180	        used_guids: BTreeSet::new(),
181	        lib: LibGuids::default(),
182	        walls: BTreeMap::new(),
183	        type_names: BTreeMap::new(),
184	        slabs: Default::default(),
185	        roofs: Default::default(),
186	        structure: Default::default(),
187	        circulation: Default::default(),
188	        components: Default::default(),
189	        params: Default::default(),
190	    };
191	    levels(&mut ctx);
192	    elements(&mut ctx);
193	    let moved = move_near_origin(&mut ctx);
194	    build::renumber(&mut ctx.pr, &ctx.lib);
195	    let reply = reply(&ctx, &schema, &name, path, moved);
196	    Ok((ctx.pr, reply))
197	}
198	
199	/// The storeys as levels, from the lowest up (ties in the file's order), named apart.
200	fn levels(ctx: &mut Ctx) {
201	    let mut found: Vec<(f64, u64, String)> = Vec::new();
202	    for id in ctx.m.of("IFCBUILDINGSTOREY").to_vec() {
203	        let e = ctx.m.get(id).unwrap();
204	        let elev = match e.p(5).r() {
205	            Some(lp) if ctx.m.get(lp).map(|x| x.name == "IFCLOCALPLACEMENT").unwrap_or(false) => geom::placement(&ctx.m, lp).t[2],
206	            _ => e.p(9).num().map(|x| x * ctx.m.scale).filter(|x| x.is_finite()).unwrap_or(0.0),
207	        };
208	        let name = e.p(2).str().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).unwrap_or_else(|| "Level".to_string());
209	        found.push((build::r3(elev), id, name));
210	    }
211	    found.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal).then(a.1.cmp(&b.1)));
212	    let mut used: Vec<String> = Vec::new();
213	    for (elev, id, name) in found {
214	        let mut n = name.clone();
215	        let mut k = 2;
216	        while used.contains(&n) {
217	            n = format!("{} ({})", name, k);
218	            k += 1;
219	        }
220	        used.push(n.clone());
221	        let g = ctx.guid_for(id);
222	        let v = crate::jobj! {
223	            "guid" => g.as_str(),
224	            "category" => "level",
225	            "name" => n.as_str(),
226	            "elevation" => elev,
227	            "view_range" => crate::jobj!{"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0},
228	        };
229	        ctx.add(id, v);
230	        ctx.levels.push(Lvl { ent: Some(id), name: n, elevation: elev, guid: g });
231	    }
232	    if ctx.levels.is_empty() {
233	        let g = crate::rand::guid();
234	        let v = crate::jobj! {
235	            "guid" => g.as_str(),
236	            "category" => "level",
237	            "name" => "Level 1",
238	            "elevation" => 0.0,
239	            "view_range" => crate::jobj!{"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0},
240	        };
241	        let id = ctx.pr.alloc_id();
242	        ctx.pr.elements.insert(id, v);
243	        ctx.levels.push(Lvl { ent: None, name: "Level 1".into(), elevation: 0.0, guid: g });
244	    }
245	}
246	
247	/// The elements, kind by kind.
248	fn elements(ctx: &mut Ctx) {
249	    // the passes in the order the original makes the elements (and so numbers them)
250	    super::import_walls::walls(ctx);
251	    super::import_slabs::floors(ctx);
252	    super::import_slabs::ceilings(ctx);
253	    super::import_roofs::roofs(ctx);
254	    super::import_slabs::shafts(ctx);
255	    super::import_circulation::masses(ctx);
256	    super::import_structure::columns(ctx);
257	    super::import_structure::runs(ctx);
258	    super::import_structure::rebar(ctx);
259	    super::import_structure::grids(ctx);
260	    super::import_components::components(ctx);
261	    super::import_circulation::stairs(ctx);
262	    super::import_circulation::railings(ctx);
263	    super::import_walls::openings(ctx);
264	    super::import_circulation::separators(ctx);
265	    super::import_rooms::rooms(ctx);
266	    // what comes after every element is in: walls attached to roofs, parameters and phases
267	    super::import_roofs::attach(ctx);
268	    super::import_params::params(ctx);
269	}
270	
271	/// A model at map coordinates moved near the origin: by the lowest corner of what came in, when
272	/// that is further than 100 km away.
273	fn move_near_origin(ctx: &mut Ctx) -> Value {
274	    let mut lo = [f64::INFINITY, f64::INFINITY];
275	    for e in ctx.pr.elements.values() {
276	        for k in ["start", "end", "at", "point"] {
277	            if let Some(p) = e.get(k).and_then(|p| p.as_arr()) {
278	                if let (Some(x), Some(y)) = (p.first().and_then(|v| v.as_f64()), p.get(1).and_then(|v| v.as_f64())) {
279	                    lo[0] = lo[0].min(x);
280	                    lo[1] = lo[1].min(y);
281	                }
282	            }
283	        }
284	        for k in ["boundary", "path"] {
285	            if let Some(a) = e.get(k).and_then(|p| p.as_arr()) {
286	                for p in a {
287	                    if let Some(p) = p.as_arr() {
288	                        if let (Some(x), Some(y)) = (p.first().and_then(|v| v.as_f64()), p.get(1).and_then(|v| v.as_f64())) {
289	                            lo[0] = lo[0].min(x);
290	                            lo[1] = lo[1].min(y);
291	                        }
292	                    }
293	                }
294	            }
295	        }
296	    }
297	    if !lo[0].is_finite() || !(lo[0].abs() > 1e8 || lo[1].abs() > 1e8) {
298	        return Value::Null;
299	    }
300	    let (dx, dy) = (-lo[0], -lo[1]);
301	    let shift = |p: &mut Value| {
302	        if let Some(a) = p.as_arr_mut() {
303	            if a.len() >= 2 {
304	                if let (Some(x), Some(y)) = (a[0].as_f64(), a[1].as_f64()) {
305	                    a[0] = Value::f(build::r3(x + dx));
306	                    a[1] = Value::f(build::r3(y + dy));
307	                }
308	            }
309	        }
310	    };
311	    for e in ctx.pr.elements.values_mut() {
312	        for k in ["start", "end", "at", "point"] {
313	            if let Some(p) = e.get_mut(k) {
314	                shift(p);
315	            }
316	        }
317	        for k in ["boundary", "path"] {
318	            if let Some(Value::Arr(a)) = e.get_mut(k) {
319	                for p in a.iter_mut() {
320	                    shift(p);
321	                }
322	            }
323	        }
324	    }
325	    Value::Arr(vec![Value::f(dx), Value::f(dy)])
326	}
327	
328	fn reply(ctx: &Ctx, schema: &str, name: &str, path: &str, moved: Value) -> Value {
329	    let mut counts: BTreeMap<String, u64> = BTreeMap::new();
330	    for e in ctx.pr.elements.values() {
331	        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
332	        *counts.entry(c).or_insert(0) += 1;
333	    }
334	    let mut m = Map::new();
335	    for (k, v) in counts {
336	        m.insert(&k, Value::u(v));
337	    }
338	    crate::jobj! {
339	        "elements" => Value::Obj(m),
340	        "format" => schema,
341	        "moved" => moved,
342	        "name" => name,
343	        "path" => path,
344	        "skipped" => Value::Arr(ctx.skipped.iter().map(|s| Value::s(s)).collect()),
345	    }
346	}
