1	//! Building the project an IFC import makes: a new project's library and sections, the types
2	//! the file's elements need (named apart when they differ), and the library numbered again in
3	//! the order a project lists it.
4	
5	use crate::json::{Map, Value};
6	use crate::project::Project;
7	use std::collections::BTreeMap;
8	
9	/// A new project as an import starts it: the default library, no elements.
10	pub fn new_project(name: &str) -> Project {
11	    let mut pr = Project::new("en");
12	    pr.elements.clear();
13	    pr.doc.insert("name", Value::s(name));
14	    pr.doc.insert("next_id", Value::u(100000));
15	    pr
16	}
17	
18	/// Rounds a length to a thousandth of a millimetre, as the import writes them (a negative zero
19	/// stays one).
20	pub fn r3(x: f64) -> f64 {
21	    (x * 1000.0).round() / 1000.0
22	}
23	
24	/// Rounds to a hundredth (a roof's slope and thickness, a sill), a negative zero made zero.
25	pub fn r2(x: f64) -> f64 {
26	    let v = (x * 100.0).round() / 100.0;
27	    if v == 0.0 {
28	        0.0
29	    } else {
30	        v
31	    }
32	}
33	
34	/// r3 with a negative zero made zero.
35	pub fn r3z(x: f64) -> f64 {
36	    let v = r3(x);
37	    if v == 0.0 {
38	        0.0
39	    } else {
40	        v
41	    }
42	}
43	
44	/// Rounds to a millionth (an angle in degrees).
45	pub fn r6(x: f64) -> f64 {
46	    let v = (x * 1e6).round() / 1e6;
47	    if v == 0.0 {
48	        0.0
49	    } else {
50	        v
51	    }
52	}
53	
54	/// A number as a name shows it: `200`, `152.5`.
55	pub fn num_name(x: f64) -> String {
56	    let v = r3(x);
57	    if v == v.trunc() && v.abs() < 1e15 {
58	        format!("{}", v as i64)
59	    } else {
60	        format!("{}", v)
61	    }
62	}
63	
64	/// A value with its `id` and `guid` keys taken out, at any depth (to compare types).
65	pub fn strip_ids(v: &Value) -> Value {
66	    match v {
67	        Value::Obj(m) => {
68	            let mut o = Map::new();
69	            for (k, x) in &m.items {
70	                if k == "id" || k == "guid" {
71	                    continue;
72	                }
73	                o.items.push((k.clone(), strip_ids(x)));
74	            }
75	            Value::Obj(o)
76	        }
77	        Value::Arr(a) => Value::Arr(a.iter().map(strip_ids).collect()),
78	        _ => v.clone(),
79	    }
80	}
81	
82	pub fn is_run(cat: &str) -> bool {
83	    matches!(
84	        cat,
85	        "beam" | "cable" | "cabletray" | "conduit" | "downconductor" | "duct" | "groundconductor" | "pipe" | "stripfooting" | "wire"
86	    )
87	}
88	
89	/// The types section of a category (`wall`, …, or a run kind under `runs`).
90	pub fn types_map<'a>(pr: &'a mut Project, cat: &str) -> &'a mut Map {
91	    let types = pr.section_mut("types");
92	    let (outer, inner) = if is_run(cat) { ("runs", Some(cat)) } else { (cat, None) };
93	    if !types.contains(outer) {
94	        types.insert(outer, Value::obj());
95	    }
96	    let mut m = types.get_mut(outer).unwrap().as_obj_mut().unwrap();
97	    if let Some(i) = inner {
98	        if !m.contains(i) {
99	            m.insert_sorted(i, Value::obj());
100	        }
101	        m = m.get_mut(i).unwrap().as_obj_mut().unwrap();
102	    }
103	    m
104	}
105	
106	pub fn type_value<'a>(pr: &'a Project, cat: &str, name: &str) -> Option<&'a Value> {
107	    let types = pr.section("types")?;
108	    if is_run(cat) {
109	        types.get("runs")?.get(cat)?.get(name)
110	    } else {
111	        types.get(cat)?.get(name)
112	    }
113	}
114	
115	/// Adds a type under a name, or finds the one that is the same; another with the same name and
116	/// other values is named `Name (2)`, `Name (3)`…. Returns the name it has.
117	pub fn add_type(pr: &mut Project, cat: &str, name: &str, v: Value) -> String {
118	    let m = types_map(pr, cat);
119	    let want = strip_ids(&v);
120	    let mut k = 1;
121	    loop {
122	        let cand = if k == 1 { name.to_string() } else { format!("{} ({})", name, k) };
123	        match m.get(&cand) {
124	            Some(x) => {
125	                if strip_ids(x) == want {
126	                    return cand;
127	                }
128	            }
129	            None => {
130	                m.insert_sorted(&cand, v);
131	                return cand;
132	            }
133	        }
134	        k += 1;
135	    }
136	}
137	
138	/// The library kind of a type of a category.
139	pub fn type_kind(cat: &str) -> String {
140	    match cat {
141	        "structural_column" => "type:structuralcolumn".to_string(),
142	        _ => format!("type:{}", cat),
143	    }
144	}
145	
146	/// The GUIDs library entries are to have, by (kind, name), before the library is numbered.
147	#[derive(Default)]
148	pub struct LibGuids {
149	    pub map: BTreeMap<(String, String), String>,
150	}
151	
152	impl LibGuids {
153	    /// The GUID of an entry: the one the library has, the one given before, or a new one.
154	    pub fn get(&mut self, pr: &Project, kind: &str, name: &str) -> String {
155	        if let Some(g) = pr.lib_guid(kind, name) {
156	            return g;
157	        }
158	        self.map.entry((kind.to_string(), name.to_string())).or_insert_with(crate::rand::guid).clone()
159	    }
160	}
161	
162	const DEFAULT_PHASES: &[&str] = &["Existing", "New Construction"];
163	const DEFAULT_PHASE_FILTERS: &[&str] = &["Show All", "Show Complete", "Show New", "Show Previous + Demolished", "Show Previous + New"];
164	
165	/// The library's entries in the order a project lists them.
166	fn library_order(pr: &Project) -> Vec<(String, String)> {
167	    let mut out: Vec<(String, String)> = Vec::new();
168	    let keys = |k: &str| -> Vec<String> { pr.section(k).map(|m| m.keys().cloned().collect()).unwrap_or_default() };
169	    if let Some(types) = pr.section("types") {
170	        for (cat, ts) in types.iter() {
171	            if cat == "runs" {
172	                if let Some(runs) = ts.as_obj() {
173	                    for (run, rts) in runs.iter() {
174	                        if let Some(rts) = rts.as_obj() {
175	                            for (name, _) in rts.iter() {
176	                                out.push((format!("type:{}", run), name.clone()));
177	                            }
178	                        }
179	                    }
180	                }
181	                continue;
182	            }
183	            if let Some(ts) = ts.as_obj() {
184	                for (name, _) in ts.iter() {
185	                    out.push((type_kind(cat), name.clone()));
186	                }
187	            }
188	        }
189	    }
190	    for n in keys("materials") {
191	        out.push(("material".into(), n));
192	    }
193	    for n in keys("images") {
194	        out.push(("image".into(), n));
195	    }
196	    for n in keys("families") {
197	        out.push(("family".into(), n));
198	    }
199	    for n in keys("parameters") {
200	        out.push(("parameter".into(), n));
201	    }
202	    for n in keys("view_filters") {
203	        out.push(("view-filter".into(), n));
204	    }
205	    for n in keys("view_templates") {
206	        out.push(("view-template".into(), n));
207	    }
208	    match pr.doc.get("phases").and_then(|p| p.as_arr()) {
209	        Some(a) => {
210	            for p in a {
211	                if let Some(s) = p.as_str() {
212	                    out.push(("phase".into(), s.to_string()));
213	                }
214	            }
215	        }
216	        None => {
217	            for p in DEFAULT_PHASES {
218	                out.push(("phase".into(), p.to_string()));
219	            }
220	        }
221	    }
222	    match pr.section("phase_filters") {
223	        Some(m) => {
224	            for n in m.keys() {
225	                out.push(("phase-filter".into(), n.clone()));
226	            }
227	        }
228	        None => {
229	            for p in DEFAULT_PHASE_FILTERS {
230	                out.push(("phase-filter".into(), p.to_string()));
231	            }
232	        }
233	    }
234	    if let Some(os) = pr.section("option_sets") {
235	        for n in os.keys() {
236	            out.push(("option-set".into(), n.clone()));
237	        }
238	        for (n, s) in os.iter() {
239	            if let Some(opts) = s.get("options").and_then(|o| o.as_arr()) {
240	                for o in opts {
241	                    if let Some(o) = o.as_str() {
242	                        out.push(("design-option".into(), format!("{}: {}", n, o)));
243	                    }
244	                }
245	            }
246	        }
247	    }
248	    if let Some(f) = pr.section("families") {
249	        for (name, fv) in f.iter() {
250	            if let Some(ts) = fv.get("types").and_then(|t| t.as_obj()) {
251	                for (t, _) in ts.iter() {
252	                    out.push(("family-type".into(), format!("{}: {}", name, t)));
253	                }
254	            }
255	        }
256	        for (name, fv) in f.iter() {
257	            if let Some(ps) = fv.get("parameters").and_then(|p| p.as_arr()) {
258	                for p in ps {
259	                    if let Some(n) = p.get("name").and_then(|n| n.as_str()) {
260	                        out.push(("family-parameter".into(), format!("{}: {}", name, n)));
261	                    }
262	                }
263	            }
264	        }
265	    }
266	    for (sec, kind) in [
267	        ("line_patterns", "line-pattern"),
268	        ("line_styles", "line-style"),
269	        ("fill_patterns", "fill-pattern"),
270	        ("region_types", "filled-region-type"),
271	        ("text_types", "text-type"),
272	        ("dimension_types", "dimension-type"),
273	        ("detail_groups", "detail-group"),
274	        ("voltages", "voltage"),
275	        ("distribution_systems", "distribution-system"),
276	        ("wire_types", "wire-type"),
277	    ] {
278	        for n in keys(sec) {
279	            out.push((kind.into(), n));
280	        }
281	    }
282	    out
283	}
284	
285	/// Numbers the library again from 999999 down, in the order a project lists it, each entry
286	/// keeping its GUID (the library's, else the one given, else a new one); then the parts that
287	/// carry ids (types' layers, families' forms, symbols and connectors) after them.
288	pub fn renumber(pr: &mut Project, given: &LibGuids) {
289	    let order = library_order(pr);
290	    let mut lib: BTreeMap<u64, Value> = BTreeMap::new();
291	    let mut id = 999_999u64;
292	    for (kind, name) in order {
293	        let g = pr
294	            .lib_guid(&kind, &name)
295	            .or_else(|| given.map.get(&(kind.clone(), name.clone())).cloned())
296	            .unwrap_or_else(crate::rand::guid);
297	        lib.insert(id, crate::jobj! {"kind" => kind.as_str(), "name" => name.as_str(), "guid" => g});
298	        id -= 1;
299	    }
300	    pr.library = lib;
301	    // the parts
302	    let set_id = |item: &mut Value, id: &mut u64| {
303	        if let Value::Obj(m) = item {
304	            let mut n = Map::new();
305	            n.items.push(("id".into(), Value::u(*id)));
306	            if !m.contains("guid") {
307	                n.items.push(("guid".into(), Value::s(&crate::rand::guid())));
308	            }
309	            for (k, x) in m.items.drain(..) {
310	                if k == "id" {
311	                    continue;
312	                }
313	                n.items.push((k, x));
314	            }
315	            *m = n;
316	            *id -= 1;
317	        }
318	    };
319	    if let Some(Value::Obj(types)) = pr.doc.get_mut("types") {
320	        for (cat, ts) in types.items.iter_mut() {
321	            if cat == "runs" {
322	                continue;
323	            }
324	            if let Value::Obj(ts) = ts {
325	                for (_, t) in ts.items.iter_mut() {
326	                    if let Some(Value::Arr(ls)) = t.get_mut("layers") {
327	                        for l in ls.iter_mut() {
328	                            set_id(l, &mut id);
329	                        }
330	                    }
331	                }
332	            }
333	        }
334	    }
335	    if let Some(Value::Obj(fams)) = pr.doc.get_mut("families") {
336	        for (_, f) in fams.items.iter_mut() {
337	            for part in ["forms", "symbols", "connectors"] {
338	                if let Some(Value::Arr(ls)) = f.get_mut(part) {
339	                    for l in ls.iter_mut() {
340	                        set_id(l, &mut id);
341	                    }
342	                }
343	            }
344	        }
345	    }
346	    // the elements' parts: a shaped floor's or roof's points and lines
347	    for (_, e) in pr.elements.iter_mut() {
348	        if let Some(sh) = e.get_mut("shape") {
349	            for part in ["points", "lines"] {
350	                if let Some(Value::Arr(ls)) = sh.get_mut(part) {
351	                    for l in ls.iter_mut() {
352	                        set_id(l, &mut id);
353	                    }
354	                }
355	            }
356	        }
357	    }
358	    pr.lib_low = id + 1;
359	}
