137	pub fn p2(m: &Model, id: u64) -> Option<V2> {
138	    let e = m.get(id)?;
139	    if e.name != "IFCCARTESIANPOINT" {
140	        return None;
141	    }
142	    let c = e.p(0).nums()?;
143	    Some([*c.first().unwrap_or(&0.0) * m.scale, *c.get(1).unwrap_or(&0.0) * m.scale])
144	}
