146	pub fn p3(m: &Model, id: u64) -> Option<V3> {
147	    let e = m.get(id)?;
148	    if e.name != "IFCCARTESIANPOINT" {
149	        return None;
150	    }
151	    let c = e.p(0).nums()?;
152	    Some([
153	        *c.first().unwrap_or(&0.0) * m.scale,
154	        *c.get(1).unwrap_or(&0.0) * m.scale,
155	        *c.get(2).unwrap_or(&0.0) * m.scale,
156	    ])
157	}
