159	pub fn dir3(m: &Model, p: &P) -> Option<V3> {
160	    let e = m.get(p.r()?)?;
161	    if e.name != "IFCDIRECTION" {
162	        return None;
163	    }
164	    let c = e.p(0).nums()?;
165	    Some([*c.first().unwrap_or(&0.0), *c.get(1).unwrap_or(&0.0), *c.get(2).unwrap_or(&0.0)])
166	}
