168	/// IFC's first projected axis: `v` (or the default) made square to `z`.
169	fn first_proj(z: V3, v: Option<V3>) -> V3 {
170	    let v = match v {
171	        Some(v) => v,
172	        None => {
173	            if z != [1.0, 0.0, 0.0] {
174	                [1.0, 0.0, 0.0]
175	            } else {
176	                [0.0, 1.0, 0.0]
177	            }
178	        }
179	    };
180	    unit(sub(v, mul(z, dot(v, z))))
181	}
