183	/// An IfcAxis2Placement3D (or 2D) as a map.
184	pub fn axis_placement(m: &Model, id: u64) -> Tf {
185	    let e = match m.get(id) {
186	        Some(e) => e,
187	        None => return Tf::ID,
188	    };
189	    match e.name.as_str() {
190	        "IFCAXIS2PLACEMENT3D" => {
191	            let t = e.p(0).r().and_then(|r| p3(m, r)).unwrap_or([0.0; 3]);
192	            let z = unit(dir3(m, e.p(1)).unwrap_or([0.0, 0.0, 1.0]));
193	            let x = first_proj(z, dir3(m, e.p(2)));
194	            let y = cross(z, x);
195	            Tf { x, y, z, t }
196	        }
197	        "IFCAXIS2PLACEMENT2D" => {
198	            let o = e.p(0).r().and_then(|r| p2(m, r)).unwrap_or([0.0; 2]);
199	            let d = dir3(m, e.p(1)).unwrap_or([1.0, 0.0, 0.0]);
200	            let x = unit([d[0], d[1], 0.0]);
201	            Tf { x, y: [-x[1], x[0], 0.0], z: [0.0, 0.0, 1.0], t: [o[0], o[1], 0.0] }
202	        }
203	        _ => Tf::ID,
204	    }
205	}
