207	/// An IfcLocalPlacement (or a grid placement, as its origin) in the project's coordinates.
208	pub fn placement(m: &Model, id: u64) -> Tf {
209	    let mut chain: Vec<Tf> = Vec::new();
210	    let mut cur = Some(id);
211	    let mut guard = 0;
212	    while let Some(c) = cur {
213	        guard += 1;
214	        if guard > 1000 {
215	            break;
216	        }
217	        let e = match m.get(c) {
218	            Some(e) => e,
219	            None => break,
220	        };
221	        if e.name != "IFCLOCALPLACEMENT" {
222	            break;
223	        }
224	        chain.push(e.p(1).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID));
225	        cur = e.p(0).r();
226	    }
227	    let mut t = Tf::ID;
228	    for l in chain.iter().rev() {
229	        t = t.then(l);
230	    }
231	    t
232	}
