234	/// An IfcCartesianTransformationOperator (2D or 3D, uniform or not).
235	pub fn operator(m: &Model, id: u64) -> Tf {
236	    let e = match m.get(id) {
237	        Some(e) => e,
238	        None => return Tf::ID,
239	    };
240	    let is2d = e.name.starts_with("IFCCARTESIANTRANSFORMATIONOPERATOR2D");
241	    let a1 = dir3(m, e.p(0));
242	    let a2 = dir3(m, e.p(1));
243	    let o = e.p(2).r().and_then(|r| p3(m, r)).unwrap_or([0.0; 3]);
244	    let s = e.p(3).num().unwrap_or(1.0);
245	    let (x, y, z);
246	    if is2d {
247	        let d1 = unit(a1.map(|d| [d[0], d[1], 0.0]).unwrap_or([1.0, 0.0, 0.0]));
248	        x = d1;
249	        y = a2.map(|d| unit([d[0], d[1], 0.0])).unwrap_or([-d1[1], d1[0], 0.0]);
250	        z = [0.0, 0.0, 1.0];
251	    } else {
252	        let a3 = dir3(m, e.p(4));
253	        let d1 = unit(a3.unwrap_or([0.0, 0.0, 1.0]));
254	        let d2 = first_proj(d1, a1);
255	        let v = a2.unwrap_or([0.0, 1.0, 0.0]);
256	        let d3 = unit(sub(sub(v, mul(d1, dot(v, d1))), mul(d2, dot(v, d2))));
257	        x = d2;
258	        y = d3;
259	        z = d1;
260	    }
261	    let (s2, s3) = if e.name.ends_with("NONUNIFORM") {
262	        if is2d {
263	            (e.p(4).num().unwrap_or(s), 1.0)
264	        } else {
265	            (e.p(5).num().unwrap_or(s), e.p(6).num().unwrap_or(s))
266	        }
267	    } else {
268	        (s, if is2d { 1.0 } else { s })
269	    };
270	    Tf { x: mul(x, s), y: mul(y, s2), z: mul(z, s3), t: o }
271	}
