275	/// Points along an arc of a circle (centre, radius) from angle a0 to a1 (radians, a1 > a0 for
276	/// counter-clockwise), both ends included.
277	pub fn arc_points(c: V2, r: f64, a0: f64, a1: f64) -> Vec<V2> {
278	    let sweep = a1 - a0;
279	    let n = ((sweep.abs() / (2.0 * std::f64::consts::PI) * CIRCLE_SEGMENTS as f64).ceil() as usize).max(1);
280	    (0..=n)
281	        .map(|i| {
282	            let a = a0 + sweep * i as f64 / n as f64;
283	            [c[0] + r * a.cos(), c[1] + r * a.sin()]
284	        })
285	        .collect()
286	}
287	
288	/// The circle through three points (centre, radius), if they are not in a line.
289	pub fn circle3(a: V2, b: V2, c: V2) -> Option<(V2, f64)> {
290	    let d = 2.0 * (a[0] * (b[1] - c[1]) + b[0] * (c[1] - a[1]) + c[0] * (a[1] - b[1]));
291	    if d.abs() < 1e-12 {
292	        return None;
293	    }
294	    let a2 = a[0] * a[0] + a[1] * a[1];
295	    let b2 = b[0] * b[0] + b[1] * b[1];
296	    let c2 = c[0] * c[0] + c[1] * c[1];
297	    let ux = (a2 * (b[1] - c[1]) + b2 * (c[1] - a[1]) + c2 * (a[1] - b[1])) / d;
298	    let uy = (a2 * (c[0] - b[0]) + b2 * (a[0] - c[0]) + c2 * (b[0] - a[0])) / d;
299	    let r = ((a[0] - ux).powi(2) + (a[1] - uy).powi(2)).sqrt();
300	    Some(([ux, uy], r))
301	}
