303	/// A curve's points in its own coordinates (3D; a 2D curve has z = 0), and whether it is closed
304	/// by its nature (a circle).
305	pub fn curve(m: &Model, id: u64) -> Option<Vec<V3>> {
306	    let e = m.get(id)?;
307	    match e.name.as_str() {
308	        "IFCPOLYLINE" => {
309	            let mut v = Vec::new();
310	            for r in e.p(0).refs() {
311	                v.push(p3(m, r)?);
312	            }
313	            Some(v)
314	        }
315	        "IFCINDEXEDPOLYCURVE" => indexed_polycurve(m, e),
316	        "IFCCOMPOSITECURVE" | "IFCCOMPOSITECURVEONSURFACE" => {
317	            let mut out: Vec<V3> = Vec::new();
318	            for seg in e.p(0).refs() {
319	                let s = m.get(seg)?;
320	                // IfcCompositeCurveSegment(Transition, SameSense, ParentCurve)
321	                let parent = s.p(2).r()?;
322	                let mut pts = curve(m, parent)?;
323	                if s.p(1).boolean() == Some(false) {
324	                    pts.reverse();
325	                }
326	                for p in pts {
327	                    if let Some(l) = out.last() {
328	                        if norm(sub(*l, p)) < 1e-9 {
329	                            continue;
330	                        }
331	                    }
332	                    out.push(p);
333	                }
334	            }
335	            Some(out)
336	        }
337	        "IFCTRIMMEDCURVE" => trimmed(m, e),
338	        "IFCCIRCLE" => {
339	            let tf = e.p(0).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID);
340	            let r = e.p(1).num()? * m.scale;
341	            let pts = arc_points([0.0, 0.0], r, 0.0, 2.0 * std::f64::consts::PI);
342	            let mut v: Vec<V3> = pts.iter().map(|p| tf.apply([p[0], p[1], 0.0])).collect();
343	            v.pop();
344	            v.push(v[0]);
345	            Some(v)
346	        }
347	        "IFCELLIPSE" => {
348	            let tf = e.p(0).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID);
349	            let a = e.p(1).num()? * m.scale;
350	            let b = e.p(2).num()? * m.scale;
351	            let n = CIRCLE_SEGMENTS;
352	            let mut v: Vec<V3> = (0..n)
353	                .map(|i| {
354	                    let t = 2.0 * std::f64::consts::PI * i as f64 / n as f64;
355	                    tf.apply([a * t.cos(), b * t.sin(), 0.0])
356	                })
357	                .collect();
358	            v.push(v[0]);
359	            Some(v)
360	        }
361	        "IFCLINE" => None,
362	        _ => None,
363	    }
364	}
