366	fn indexed_polycurve(m: &Model, e: &Entity) -> Option<Vec<V3>> {
367	    let pl = m.get(e.p(0).r()?)?;
368	    let coords: Vec<V3> = pl
369	        .p(0)
370	        .list()?
371	        .iter()
372	        .filter_map(|c| {
373	            let v = c.nums()?;
374	            Some([
375	                *v.first().unwrap_or(&0.0) * m.scale,
376	                *v.get(1).unwrap_or(&0.0) * m.scale,
377	                *v.get(2).unwrap_or(&0.0) * m.scale,
378	            ])
379	        })
380	        .collect();
381	    let at = |i: i64| -> Option<V3> { coords.get((i - 1) as usize).copied() };
382	    let mut out: Vec<V3> = Vec::new();
383	    let push = |out: &mut Vec<V3>, p: V3| {
384	        if let Some(l) = out.last() {
385	            if norm(sub(*l, p)) < 1e-9 {
386	                return;
387	            }
388	        }
389	        out.push(p);
390	    };
391	    match e.p(1) {
392	        P::List(segs) if !segs.is_empty() => {
393	            for s in segs {
394	                match s {
395	                    P::Typed(n, v) => {
396	                        let idx: Vec<i64> = v.first().and_then(|l| l.list()).map(|l| l.iter().filter_map(|x| x.int()).collect()).unwrap_or_default();
397	                        if n == "IFCARCINDEX" && idx.len() == 3 {
398	                            let (a, b, c) = (at(idx[0])?, at(idx[1])?, at(idx[2])?);
399	                            for p in arc3(a, b, c) {
400	                                push(&mut out, p);
401	                            }
402	                        } else {
403	                            for i in idx {
404	                                push(&mut out, at(i)?);
405	                            }
406	                        }
407	                    }
408	                    _ => {}
409	                }
410	            }
411	        }
412	        _ => {
413	            for p in coords.iter() {
414	                push(&mut out, *p);
415	            }
416	        }
417	    }
418	    Some(out)
419	}
