421	/// Points along the arc through three points (in a plane of constant z).
422	pub fn arc3(a: V3, b: V3, c: V3) -> Vec<V3> {
423	    let (cc, r) = match circle3([a[0], a[1]], [b[0], b[1]], [c[0], c[1]]) {
424	        Some(x) => x,
425	        None => return vec![a, b, c],
426	    };
427	    let ang = |p: V3| (p[1] - cc[1]).atan2(p[0] - cc[0]);
428	    let (a0, am, a1) = (ang(a), ang(b), ang(c));
429	    // counter-clockwise if the middle point lies on the ccw sweep from a to c
430	    let tau = 2.0 * std::f64::consts::PI;
431	    let norm_a = |x: f64| ((x % tau) + tau) % tau;
432	    let ccw_m = norm_a(am - a0);
433	    let ccw_c = norm_a(a1 - a0);
434	    let sweep = if ccw_m <= ccw_c { ccw_c } else { ccw_c - tau };
435	    arc_points(cc, r, a0, a0 + sweep).into_iter().map(|p| [p[0], p[1], a[2]]).collect()
436	}
