438	fn trimmed(m: &Model, e: &Entity) -> Option<Vec<V3>> {
439	    // IfcTrimmedCurve(BasisCurve, Trim1, Trim2, SenseAgreement, MasterRepresentation)
440	    let bid = e.p(0).r()?;
441	    let basis = m.get(bid)?;
442	    let sense = e.p(3).boolean().unwrap_or(true);
443	    let master_param = e.p(4).enm() == Some("PARAMETER");
444	    let trim = |p: &P| -> (Option<f64>, Option<V3>) {
445	        let mut par = None;
446	        let mut pt = None;
447	        if let Some(l) = p.list() {
448	            for x in l {
449	                match x {
450	                    P::Ref(r) => pt = p3(m, *r),
451	                    P::Typed(n, _) if n == "IFCPARAMETERVALUE" => par = x.num(),
452	                    _ => {}
453	                }
454	            }
455	        }
456	        (par, pt)
457	    };
458	    let (t1, q1) = trim(e.p(1));
459	    let (t2, q2) = trim(e.p(2));
460	    match basis.name.as_str() {
461	        "IFCCIRCLE" | "IFCELLIPSE" => {
462	            let tf = basis.p(0).r().map(|r| axis_placement(m, r)).unwrap_or(Tf::ID);
463	            let inv = tf.inverse_rigid();
464	            let ra = basis.p(1).num()? * m.scale;
465	            let rb = if basis.name == "IFCELLIPSE" { basis.p(2).num()? * m.scale } else { ra };
466	            let angle_of = |t: Option<f64>, q: Option<V3>| -> Option<f64> {
467	                let use_param = t.is_some() && (master_param || q.is_none());
468	                if use_param {
469	                    Some(t? * m.angle)
470	                } else {
471	                    let l = inv.apply(q?);
472	                    Some((l[1] / rb).atan2(l[0] / ra))
473	                }
474	            };
475	            let a0 = angle_of(t1, q1)?;
476	            let mut a1 = angle_of(t2, q2)?;
477	            let tau = 2.0 * std::f64::consts::PI;
478	            if sense {
479	                while a1 <= a0 {
480	                    a1 += tau;
481	                }
482	            } else {
483	                while a1 >= a0 {
484	                    a1 -= tau;
485	                }
486	            }
487	            if a0.abs() > 1e6 || a1.abs() > 1e6 {
488	                return None;
489	            }
490	            let sweep = a1 - a0;
491	            let n = ((sweep.abs() / tau * CIRCLE_SEGMENTS as f64).ceil() as usize).max(1);
492	            let pts: Vec<V3> = (0..=n)
493	                .map(|i| {
494	                    let a = a0 + sweep * i as f64 / n as f64;
495	                    tf.apply([ra * a.cos(), rb * a.sin(), 0.0])
496	                })
497	                .collect();
498	            Some(pts)
499	        }
500	        "IFCLINE" => {
501	            // IfcLine(Pnt, Dir: IfcVector(Orientation, Magnitude))
502	            let o = p3(m, basis.p(0).r()?)?;
503	            let v = m.get(basis.p(1).r()?)?;
504	            let d = dir3(m, v.p(0))?;
505	            let mag = v.p(1).num().unwrap_or(1.0) * m.scale;
506	            let dv = mul(unit(d), mag);
507	            let at = |t: Option<f64>, q: Option<V3>| -> Option<V3> {
508	                if let Some(q) = q {
509	                    if !(master_param && t.is_some()) {
510	                        return Some(q);
511	                    }
512	                }
513	                Some(add(o, mul(dv, t?)))
514	            };
515	            let a = at(t1, q1)?;
516	            let b = at(t2, q2)?;
517	            Some(if sense { vec![a, b] } else { vec![b, a] })
518	        }
519	        _ => curve(m, bid),
520	    }
521	}

