/// IfcStair, IfcRamp (their flights and landings): stairs and ramps.
pub fn stairs(ctx: &mut Ctx) {
    let ids: Vec<u64> = ctx.m.of("IFCSTAIR").to_vec();
    for id in ids {
        stair(ctx, id);
    }
    let ids: Vec<u64> = ctx.m.of("IFCRAMP").to_vec();
    for id in ids {
        ramp(ctx, id);
    }
}

fn stair(ctx: &mut Ctx, id: u64) {
    let parts: Vec<u64> = ctx.m.children.get(&id).cloned().unwrap_or_default();
    let flights: Vec<u64> = parts.iter().copied().filter(|p| ctx.m.class(*p) == "IFCSTAIRFLIGHT").collect();
    if flights.is_empty() {
        ctx.skip(id, "it has no flights BIMCraft can read");
        return;
    }
    let mut fl: Vec<(Flight, i64, f64)> = Vec::new();
    for f in &flights {
        let solids = geom::body(&ctx.m, *f);
        let e = ctx.m.get(*f).unwrap();
        let risers = e.p(8).int().unwrap_or(0);
        let rh = e.p(10).num().map(|x| x * ctx.m.scale).unwrap_or(0.0);
        match stair_flight(&solids) {
            Some(x) => fl.push((x, risers, rh)),
            None => {
                ctx.skip(id, "a flight of it has no body BIMCraft can read");
                return;
            }
        }
    }
    let base = fl.iter().map(|f| f.0.z0).fold(f64::INFINITY, f64::min);
    let total: i64 = fl.iter().map(|f| f.1).sum();
    let height = fl.iter().map(|f| f.1 as f64 * f.2).sum::<f64>();
    let height = if height > 0.0 { height } else { fl.iter().map(|f| f.0.z1).fold(f64::NEG_INFINITY, f64::max) - base };
    let height = r3(height);
    let riser = if total > 0 { height / total as f64 } else { 0.0 };
    let first = &fl[0].0;
    let level = ctx.level_of(id, base);
    let top_level = ctx.level_at_top(level, base + height);
    let mut landings = Vec::new();
    let mut at = 0i64;
    for i in 0..fl.len() - 1 {
        at += fl[i].1;
        landings.push(crate::jobj! {"at" => Value::f(at as f64), "turn" => Value::f(turn(fl[i].0.dir, fl[i + 1].0.dir))});
    }
