#!/usr/bin/env python3
"""keydiff.py FILE.ifc...: convert with both programs, and list, per element category, the key paths
whose values differ (with the first example), ignoring GUIDs."""
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile

MINE = '/workspace/.claude/worktrees/agent-a269fc74daf28a975/target/release/bimcraft-cli'
G = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')


def conv(exe, f):
    d = tempfile.mkdtemp()
    shutil.copy(f, d)
    subprocess.run([exe, 'convert', os.path.basename(f), 'o.bimcraft'], cwd=d, capture_output=True)
    p = os.path.join(d, 'o.bimcraft')
    j = json.load(open(p)) if os.path.exists(p) else None
    shutil.rmtree(d)
    return j


def walk(a, b, path, out):
    if isinstance(a, dict) and isinstance(b, dict):
        for k in set(a) | set(b):
            if k in ('guid', 'id'):
                continue
            walk(a.get(k), b.get(k), path + '.' + k, out)
    elif isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
        for i, (x, y) in enumerate(zip(a, b)):
            walk(x, y, path + '[]', out)
    else:
        if isinstance(a, str) and isinstance(b, str) and G.match(a) and G.match(b):
            return
        if a != b:
            out.setdefault(path, (a, b))


for f in sys.argv[1:]:
    o = conv('/workspace/executable', f)
    m = conv(MINE, f)
    print('##', os.path.basename(f))
    if o is None or m is None:
        print('  missing output', o is None, m is None)
        continue
    out = {}
    eo, em = o['elements'], m['elements']
    for k in sorted(set(eo) | set(em)):
        a, b = eo.get(k), em.get(k)
        if a is None or b is None:
            print('  element only in one:', k, (a or b).get('category'))
            continue
        walk(a, b, a.get('category', '?'), out)
    for k in ('types', 'families', 'materials'):
        walk(o.get(k), m.get(k), k, out)
    for p, (a, b) in sorted(out.items()):
        sa, sb = json.dumps(a)[:120], json.dumps(b)[:120]
        print('  ', p, '| orig', sa, '| mine', sb)

