"""A tiny IFC writer for probing: entities by id, placements, profiles, solids."""
import random
import uuid

A = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_$"


def gid(u=None):
    n = (u or uuid.uuid4()).int
    s = ''
    for i in range(22):
        s = A[n % 64] + s
        n //= 64
    return s


def fmt(x):
    if isinstance(x, bool):
        return '.T.' if x else '.F.'
    if isinstance(x, float):
        r = repr(x)
        if 'e' in r or 'E' in r:
            m, e = r.lower().split('e')
            if '.' not in m:
                m += '.'
            return m.upper() + 'E' + str(int(e))
        if r.endswith('.0'):
            return r[:-1]
        return r
    if isinstance(x, int):
        return str(x)
    if x is None:
        return '$'
    if isinstance(x, (list, tuple)):
        return '(' + ','.join(fmt(v) for v in x) + ')'
    if isinstance(x, Raw):
        return x.s
    if isinstance(x, Ref):
        return '#%d' % x.id
    if isinstance(x, str):
        return "'" + x.replace("'", "''") + "'"
    raise TypeError(x)


class Raw:
    def __init__(self, s):
        self.s = s


class Ref:
    def __init__(self, i):
        self.id = i


def E(s):
    return Raw('.' + s + '.')


class F:
    def __init__(self, schema='IFC4', units='mm'):
        self.schema = schema
        self.lines = []
        self.n = 0
        self.units = units
        self.contained = {}
        self.types = {}

    def add(self, name, *args):
        self.n += 1
        self.lines.append('#%d=%s(%s);' % (self.n, name, ','.join(fmt(a) for a in args)))
        return Ref(self.n)

    def raw(self, text):
        self.n += 1
        self.lines.append('#%d=%s;' % (self.n, text))
        return Ref(self.n)

    def pt(self, *c):
        return self.add('IFCCARTESIANPOINT', tuple(float(v) for v in c))

