        && outline.len() == 4
        && outline.iter().all(|p| rect.iter().any(|q| (p[0] - q[0]).abs() < 0.5 && (p[1] - q[1]).abs() < 0.5));
    if !ok {
        return Some(Err("its outline isn't the rectangle its profile sweeps"));
    }
    Some(Ok(Ext { a, b, profile, width: c1 - c0, z0 }))
}

