"""findlog.py WORD [max] [width]: passages of the earlier transcript (text and tool inputs) with WORD."""
import json
import sys

word = sys.argv[1]
mx = int(sys.argv[2]) if len(sys.argv) > 2 else 8
w = int(sys.argv[3]) if len(sys.argv) > 3 else 800
p = '/logs/agent/sessions/projects/-workspace/deb8325a-ba87-4aab-9f70-12df49b67f07/subagents/agent-a269fc74daf28a975.jsonl'
hits = 0
for i, l in enumerate(open(p).read().split('\n')):
    if word not in l:
        continue
    try:
        d = json.loads(l)
    except Exception:
        continue
    cs = d.get('message', {}).get('content')
    if isinstance(cs, str):
        cs = [{'type': 'text', 'text': cs}]
    for c in cs or []:
        if c.get('type') == 'text':
            t = c.get('text', '')
        elif c.get('type') == 'tool_use':
            t = json.dumps(c.get('input', ''))
        elif c.get('type') == 'tool_result':
            cc = c.get('content')
            t = cc if isinstance(cc, str) else ' '.join(x.get('text', '') for x in (cc or []) if isinstance(x, dict))
        else:
            t = ''
        k = t.find(word)
        if k >= 0:
            print('#%d %s:' % (i, c.get('type')), t[max(0, k - w):k + w].replace('\\n', '\n'))
            print('-----')
            hits += 1
    if hits >= mx:
        break

