"""breps.py FILE REP_ID: the faceted breps of a shape representation, each face's points."""
import re
import sys

path, rep = sys.argv[1], int(sys.argv[2])
ents = {}
for line in open(path):
    m = re.match(r'#(\d+)=([A-Z0-9]+)\((.*)\);\s*$', line.strip())
    if m:
        ents[int(m.group(1))] = (m.group(2), m.group(3))


def refs(s):
    return [int(x) for x in re.findall(r'#(\d+)', s)]


def pt(i):
    n, a = ents[i]
    return tuple(float(x) for x in re.findall(r'[-0-9.E+]+', a.split('(')[1].split(')')[0]))


n, a = ents[rep]
items = refs(a.split(',', 3)[3]) if n == 'IFCSHAPEREPRESENTATION' else [rep]
for it in items:
    n, a = ents[it]
    print('item', it, n)
    if n != 'IFCFACETEDBREP':
        continue
    shell = refs(a)[0]
    for f in refs(ents[shell][1]):
        for b in refs(ents[f][1]):
            loop = refs(ents[b][1])[0]
            pts = [pt(p) for p in refs(ents[loop][1])]
            print('   face', f, ' '.join('(%.2f,%.2f,%.2f)' % p for p in pts))

