"""xotest.py: are consecutive guids xoshiro256** outputs? Solve the state from four outputs (the
masked version/variant bits tried every way), check it predicts the next."""
import itertools
import sys

M64 = (1 << 64) - 1
INV5 = pow(5, -1, 1 << 64)
INV9 = pow(9, -1, 1 << 64)


def rotl(x, k):
    return ((x << k) | (x >> (64 - k))) & M64


def rotr(x, k):
    return ((x >> k) | (x << (64 - k))) & M64


def out_to_s1(r):
    return (rotr((r * INV9) & M64, 7) * INV5) & M64


def s1_to_out(s1):
    return (rotl((s1 * 5) & M64, 7) * 9) & M64


# symbolic state: word w, bit i -> 256-bit mask over the initial state bits (w*64+i)
def sym_init():
    return [[1 << (w * 64 + i) for i in range(64)] for w in range(4)]


def sym_xor(a, b):
    return [x ^ y for x, y in zip(a, b)]


def sym_shl(a, k):
    return [a[i - k] if i >= k else 0 for i in range(64)]


def sym_rotl(a, k):
    return [a[(i - k) % 64] for i in range(64)]


def sym_step(s):
    s0, s1, s2, s3 = s
    t = sym_shl(s1, 17)
    s2 = sym_xor(s2, s0)
    s3 = sym_xor(s3, s1)
    s1 = sym_xor(s1, s2)
    s0 = sym_xor(s0, s3)
    s2 = sym_xor(s2, t)
    s3 = sym_rotl(s3, 45)
    return [s0, s1, s2, s3]


# the s1 word's masks at steps 0..5
S = sym_init()
S1 = []
for n in range(6):
    S1.append(list(S[1]))
    S = sym_step(S)


def solve(eqs):
    """eqs: list of (mask, bit). Gaussian elimination over GF(2); returns the state or None."""
    rows = {}
    for m, b in eqs:
        while m:
            p = m.bit_length() - 1
            if p in rows:
                pm, pb = rows[p]
                m ^= pm
                b ^= pb
            else:
                rows[p] = (m, b)
                break
        else:
            if b:
                return None
    if len(rows) < 256:
        return None
    # back substitution
    x = 0
    for p in sorted(rows):
        m, b = rows[p]
        rest = m & ~(1 << p)
        v = b ^ (bin(rest & x).count('1') & 1)
        if v:
            x |= 1 << p
    return x


def state_words(x):
    return [(x >> (64 * w)) & M64 for w in range(4)]


