    s = list(state)
    outs = []
    for _ in range(n):
        r = s1_to_out(s[1])
        outs.append(r)
        t = (s[1] << 17) & M64
        s[2] ^= s[0]
        s[3] ^= s[1]
        s[1] ^= s[2]
        s[0] ^= s[3]
