    b = bytes.fromhex(g.replace('-', ''))
    return int.from_bytes(b[:8], order), int.from_bytes(b[8:], order)


def free_bits(order, which):
    # where the masked bits sit in each half for a byte order
    if which == 'hi':
        return [12, 13, 14, 15] if order == 'big' else [52, 53, 54, 55]
    return [62, 63] if order == 'big' else [6, 7]


