    outs = []
    for g in seq:
        hi, lo = halves(g, order)
        pair = [(hi, 'hi'), (lo, 'lo')]
        if swap:
            pair.reverse()
        outs.extend(pair)
    first4 = outs[:4]
    frees = [free_bits(order, w) for _, w in first4]
    nfree = sum(len(f) for f in frees)
